def _contract_tensor_like(
    reference: Tensor,
    value: Optional[Tensor],
    default: float,
) -> Tensor:
    return contract_tensor_like(reference, value, default)


def _contract_certifications(
    *,
    geometry_signal: Optional[Tensor] = None,
    task_signal: Optional[Tensor] = None,
    registry_signal: Optional[Tensor] = None,
) -> Tuple[str, ...]:
    certs: list[str] = []
    if isinstance(geometry_signal, Tensor) and geometry_signal.numel() > 0:
        if float(geometry_signal.detach().float().mean().item()) > 0.0:
            certs.append("geometry_corridor")
    if isinstance(task_signal, Tensor) and task_signal.numel() > 0:
        if float(task_signal.detach().float().mean().item()) >= 0.5:
            certs.append("task_corridor")
    if isinstance(registry_signal, Tensor) and registry_signal.numel() > 0:
        if float(registry_signal.detach().float().mean().item()) > 0.0:
            certs.append("behavior_registry")
    return tuple(certs)


def _make_semantic_contract(
    *,
    value: Tensor,
    source: str,
    coverage: Optional[Tensor] = None,
    confidence: Optional[Tensor] = None,
    authority: Optional[Tensor] = None,
    trust: Optional[Tensor] = None,
    task_agreement: Optional[Tensor] = None,
    registry_support: Optional[Tensor] = None,
    semantic_debt: Optional[Tensor] = None,
    freshness: int = 0,
    certified_by: tuple[str, ...] = (),
) -> SemanticContract:
    reference = value.detach()
    return SemanticContract(
        value=reference,
        source=source,
        coverage=_contract_tensor_like(reference, coverage, 0.0),
        confidence=_contract_tensor_like(reference, confidence, 0.0),
        authority=_contract_tensor_like(reference, authority, 0.0),
        trust=_contract_tensor_like(reference, trust, 1.0),
        task_agreement=_contract_tensor_like(reference, task_agreement, 0.0),
        registry_support=_contract_tensor_like(reference, registry_support, 0.0),
        semantic_debt=_contract_tensor_like(reference, semantic_debt, 0.0),
        freshness=max(0, int(freshness)),
        certified_by=tuple(certified_by),
    )


def _compute_reward_health(
    latest_reward: float,
    best_reward: float,
) -> float:
    latest = float(latest_reward)
    best = float(best_reward)
    if not math.isfinite(latest) or not math.isfinite(best) or best <= 1e-6:
        return 1.0
    return min(1.0, max(0.0, latest / max(best, 1e-6)))


def _compute_reference_reward_agreement(
    real_targets: Optional[Tensor],
    best_reward: float,
    *,
    quantile: float = 0.75,
) -> float:
    """Estimate immediate reward agreement from the current real replay batch.

    This gives task-cert a reward-grounded signal that updates every training
    step instead of only after the next eval checkpoint lands.
    """

    if not isinstance(real_targets, Tensor) or real_targets.numel() <= 0:
        return 1.0
    finite_targets = real_targets.detach().reshape(-1).float()
    finite_targets = finite_targets[torch.isfinite(finite_targets)]
    if finite_targets.numel() <= 0:
        return 1.0
    q = min(1.0, max(0.0, float(quantile)))
    if finite_targets.numel() == 1:
        observed_reward = float(finite_targets.item())
    elif q <= 0.0:
        observed_reward = float(finite_targets.mean().item())
    elif q >= 1.0:
        observed_reward = float(finite_targets.max().item())
    else:
        observed_reward = float(torch.quantile(finite_targets, q).item())
    return _compute_reward_health(observed_reward, best_reward)


def _compute_task_cert_gate(
    *,
    task_gate: Tensor,
    task_confidence: Tensor,
    real_eval_gate: Union[float, Tensor],
    real_reward_agreement: Optional[Union[float, Tensor]] = None,
    prev_real_task_state: Optional[Union[float, Tensor]] = None,
    reward_agreement_available: bool = True,
    recovery_rate: float = 0.5,
    alarm_rate: float = 0.7,
    state_floor: float = 0.0,
) -> Tuple[Tensor, Tensor, Tensor, Tensor, Tensor]:
    certification_state = compute_task_certification_state(
        task_gate=task_gate,
        task_confidence=task_confidence,
        real_eval_gate=real_eval_gate,
        real_reward_agreement=real_reward_agreement,
        prev_real_task_state=prev_real_task_state,
        reward_agreement_available=reward_agreement_available,
        recovery_rate=recovery_rate,
        alarm_rate=alarm_rate,
        state_floor=state_floor,
    )
    return (
        certification_state.imag_task_gate,
        certification_state.real_task_state,
        certification_state.task_cert,
        certification_state.real_task_alarm,
        certification_state.real_task_recovery,
    )


