def _resolve_bootstrap_external_eval_feedback_snapshot(
    *,
    bootstrap_external_eval_feedback_telemetry: Optional[Dict[str, Any]],
    bootstrap_external_eval_feedback_last_step: int,
    global_step: int,
    corridor_semantic_corridor_mask: Tensor,
) -> Tuple[float, float, float, float, float, float, float, float]:
    """Resolve the training-time external eval feedback snapshot consumed by bootstrap entry."""

    del corridor_semantic_corridor_mask
    telemetry = bootstrap_external_eval_feedback_telemetry or {}
    resolved_available = 1.0 if bool(telemetry) else 0.0
    resolved_age_steps = (
        float(max(0, int(global_step) - int(bootstrap_external_eval_feedback_last_step)))
        if int(bootstrap_external_eval_feedback_last_step) >= 0 and resolved_available > 0.0
        else -1.0
    )
    resolved_real_reward_degradation = min(
        1.0,
        max(0.0, float(telemetry.get("real_reward_degradation", 0.0))),
    )
    resolved_real_task_cert_gate = min(
        1.0,
        max(0.0, float(telemetry.get("real_task_cert_gate", 1.0))),
    )
    resolved_real_task_cert_alarm = min(
        1.0,
        max(
            0.0,
            float(
                telemetry.get(
                    "real_task_cert_alarm",
                    1.0 - resolved_real_task_cert_gate,
                )
            ),
        ),
    )
    resolved_real_task_cert_recovery = min(
        1.0,
        max(
            0.0,
            float(
                telemetry.get(
                    "real_task_cert_recovery",
                    resolved_real_task_cert_gate,
                )
            ),
        ),
    )
    resolved_real_behavior_action_switch_rate = min(
        1.0,
        max(0.0, float(telemetry.get("real_behavior_action_switch_rate", 0.0))),
    )
    resolved_real_behavior_action_oscillation_rate = min(
        1.0,
        max(
            0.0,
            float(telemetry.get("real_behavior_action_oscillation_rate", 0.0)),
        ),
    )
    return (
        resolved_real_reward_degradation,
        resolved_real_task_cert_gate,
        resolved_real_task_cert_alarm,
        resolved_real_task_cert_recovery,
        resolved_real_behavior_action_switch_rate,
        resolved_real_behavior_action_oscillation_rate,
        resolved_available,
        resolved_age_steps,
    )

