def _allocate_priority_budget_with_capacity(
    priority: Tensor,
    capacity: Tensor,
    budget_sum: Tensor,
    *,
    passes: int = 4,
) -> Tensor:
    """Allocate per-row budget by priority while respecting per-position caps."""

    priority = priority.clamp(min=0.0)
    capacity = capacity.clamp(min=0.0, max=1.0)
    budget_sum = budget_sum.clamp(min=0.0)
    allocation = torch.zeros_like(capacity)
    remaining_budget = budget_sum
    active_priority = priority * (capacity > 1e-6).to(dtype=priority.dtype)

    for _ in range(max(1, int(passes))):
        priority_sum = active_priority.sum(dim=1, keepdim=True)
        proposal = torch.where(
            priority_sum > 0.0,
            remaining_budget * active_priority / priority_sum.clamp(min=1e-6),
            torch.zeros_like(capacity),
        )
        headroom = (capacity - allocation).clamp(min=0.0)
        taken = torch.minimum(proposal, headroom)
        allocation = allocation + taken
        remaining_budget = (remaining_budget - taken.sum(dim=1, keepdim=True)).clamp(min=0.0)
        if float(remaining_budget.max().item()) <= 1e-6:
            break
        active_priority = active_priority * (headroom > 1e-6).to(dtype=priority.dtype)

    return allocation.clamp(0.0, 1.0)


def _blend_actor_unified_contract(
    local_trust: Tensor,
    source_trust: Tensor,
    blend: float,
    *,
    trust_floor: float,
) -> tuple[Tensor, Tensor]:
    """Blend actor-local and unified semantic contract views into one coherent pair."""

    blend = min(1.0, max(0.0, float(blend)))
    floor = min(1.0, max(0.0, float(trust_floor)))
    blended_trust = torch.lerp(
        local_trust.detach().clamp(min=floor, max=1.0),
        source_trust.detach().clamp(min=floor, max=1.0),
        blend,
    ).clamp(min=floor, max=1.0)
    blended_authority = (1.0 - blended_trust).clamp(0.0, 1.0)
    return blended_trust, blended_authority


def _apply_actor_unified_tail_relief(
    base_authority: Tensor,
    local_trust: Tensor,
    advantages: Tensor,
    semantic_pressure: Tensor,
    late_gate: float,
    *,
    relief_max: float,
    adv_threshold: float,
    adv_tau: float,
    trust_floor: float,
) -> tuple[Tensor, Tensor, Tensor]:
    """Apply a small late-phase fallback toward local actor caution only in tail drift."""

    relief_cap = min(1.0, max(0.0, float(relief_max)))
    if relief_cap <= 0.0:
        authority = base_authority.detach().clamp(0.0, 1.0)
        trust = (1.0 - authority).clamp(min=max(0.0, float(trust_floor)), max=1.0)
        relief = torch.zeros_like(authority)
        return authority, trust, relief
    adv_tau = max(1e-6, float(adv_tau))
    adv_threshold = max(0.0, float(adv_threshold))
    late_gate = min(1.0, max(0.0, float(late_gate)))
    local_authority = (1.0 - local_trust.detach()).clamp(0.0, 1.0)
    negative_adv_pressure = (
        (-advantages.detach() - adv_threshold) / adv_tau
    ).clamp(0.0, 1.0)
    # Negative advantage is the hard prerequisite for tail relief.
    # Semantic pressure can only modulate the already-active tail fallback,
    # not trigger it on its own.
    semantic_modulation = 0.5 + 0.5 * semantic_pressure.detach().clamp(0.0, 1.0)
    relief_gate = (
        late_gate
        * negative_adv_pressure
        * semantic_modulation
    ).clamp(0.0, 1.0)
    relief_budget = (local_authority - base_authority.detach()).clamp(min=0.0)
    relief_surface = (
        torch.minimum(
            relief_budget,
            torch.full_like(relief_budget, relief_cap),
        )
        * relief_gate
    ).clamp(0.0, 1.0)
    authority = (base_authority.detach() + relief_surface).clamp(0.0, 1.0)
    trust = (1.0 - authority).clamp(min=max(0.0, float(trust_floor)), max=1.0)
    return authority, trust, relief_surface


