#    _get_zero_tensor()                  — cached zero-tensor factory
# ══════════════════════════════════════════════════════════════════════════════


def _get_zero_tensor(
    device: torch.device,
    shape: tuple = (),
    dtype: torch.dtype = torch.float32,
) -> torch.Tensor:
    """Create a zero tensor on *device*, reusing PyTorch's caching allocator.

    Intended for scalar loss placeholders inside training steps where
    allocation overhead would otherwise dominate.
    """
    return torch.zeros(shape, device=device, dtype=dtype)


# ── Value extraction ────────────────────────────────────────────────────────

def extract_real_value(
    value_out: Any,
    symlog_clip: float = 30.0,
) -> torch.Tensor:
    """Extract a real-scale scalar value from any critic output format.

    This is the **single point of truth** for converting CriticOutput (or a
    plain tensor) into a value suitable for GAE / advantage computation.
    Before this function existed, the conversion logic was duplicated in
    ``_compute_policy_outputs``, ``RolloutCollector``, and
    ``ImaginationEngine``—each with subtly different fallback paths.

    Supported formats
    -----------------
    1. Object with ``values_real_main`` attribute  → used directly.
    2. Object with ``values_symlog_main`` attribute → ``symexp`` applied.
    3. Plain ``torch.Tensor`` (assumed real-scale)  → used directly.

    Parameters
    ----------
    value_out :
        CriticOutput dataclass, named-tuple, or plain tensor.
    symlog_clip : float
        Maximum absolute value passed to :func:`symexp`.

    Returns
    -------
    torch.Tensor
        Shape ``[B]`` or ``[B, T]``.  A trailing singleton dimension
        (``[…, 1]``) is automatically squeezed.

    Raises
    ------
    TypeError
        If *value_out* is not a recognised format.
    """
    if hasattr(value_out, "values_real_main"):
        v = value_out.values_real_main
    elif hasattr(value_out, "values_symlog_main"):
        v = symexp(value_out.values_symlog_main, max_val=symlog_clip)
    elif isinstance(value_out, torch.Tensor):
        v = value_out
    else:
        raise TypeError(
            f"Cannot extract value from type {type(value_out).__name__}. "
            f"Expected CriticOutput (with values_real_main or "
            f"values_symlog_main) or plain Tensor."
        )
    # Squeeze trailing singleton: (B, 1) → (B)
    if v.dim() >= 2 and v.shape[-1] == 1:
        v = v.squeeze(-1)
    return v


def _compute_policy_feature_values_via_critic(
    policy_features: Optional[Tensor],
    critic: Optional[Any],
    *,
    use_target: bool = False,
    detach_inputs: bool = False,
    disable_grad: bool = False,
    allow_signature_fallback: bool = True,
) -> Optional[Tensor]:
    """Canonical policy-feature → scalar-value adapter for step and loop paths.

    ``TrainingStep`` and ``TrainingLoop`` need the same critic output shaping
    logic but intentionally differ on gradient handling.  Keeping the policy
    feature adaptation here makes that difference explicit via flags instead of
    duplicated method bodies.
    """
    if policy_features is None or critic is None or not callable(critic):
        return None

    critic_inputs = policy_features.detach() if detach_inputs else policy_features

    def _invoke_critic() -> Optional[Any]:
        try:
            return critic(critic_inputs, use_target=use_target)
        except TypeError:
            if not allow_signature_fallback:
                return None
            try:
                return critic(critic_inputs)
            except TypeError:
                return None

    if disable_grad:
        with torch.no_grad():
            values_raw = _invoke_critic()
    else:
        values_raw = _invoke_critic()

    if values_raw is None:
        return None

    values = extract_real_value(values_raw)
    if values.dim() > len(critic_inputs.shape[:-1]) and values.shape[-1] == 1:
        values = values.squeeze(-1)
    expected_shape = critic_inputs.shape[:-1]
    expected_numel = 1
    for dim in expected_shape:
        expected_numel *= int(dim)
    if values.shape != expected_shape and values.numel() == expected_numel:
        values = values.reshape(expected_shape)
    if values.shape != expected_shape:
        return None
    return values


def _policy_features_from_wm_state_via_model(
    model: Optional[Any],
    wm_state: Optional[Any],
    *,
    strict: bool = False,
    failure_context: str = "policy feature extraction",
) -> Optional[Tensor]:
    """Canonical WM-state → policy-feature adapter used by step and loop paths."""
    failure_reasons: List[str] = []

    if model is None:
        failure_reasons.append("model is None")
    if wm_state is None:
        failure_reasons.append("wm_state is None")
    if failure_reasons:
        if strict:
            raise RuntimeError(f"{failure_context} failed: {'; '.join(failure_reasons)}")
        return None

    if hasattr(model, "policy_from_wm_state"):
        try:
            features = model.policy_from_wm_state(wm_state)
        except Exception as exc:
            failure_reasons.append(
                f"model.policy_from_wm_state raised {type(exc).__name__}: {exc}"
            )
        else:
            if features is not None:
                return features
            failure_reasons.append("model.policy_from_wm_state returned None")

    world_model = getattr(model, "world_model", None)
    rssm = getattr(world_model, "state_transition", None)
    h_shared = getattr(wm_state, "h_shared", None)
    z = getattr(wm_state, "z", None)
    if rssm is None or not hasattr(rssm, "get_features"):
        failure_reasons.append("world_model.state_transition.get_features unavailable")
    elif h_shared is None or z is None:
        missing = []
        if h_shared is None:
            missing.append("h_shared")
        if z is None:
            missing.append("z")
        failure_reasons.append(
            "wm_state missing "
            + ", ".join(missing)
            + " required by state_transition.get_features"
        )
    else:
        try:
            return rssm.get_features(h_shared, z)
        except Exception as exc:
            failure_reasons.append(
                f"state_transition.get_features raised {type(exc).__name__}: {exc}"
            )

    if strict:
        detail = "; ".join(failure_reasons) if failure_reasons else "no feature extractor succeeded"
        raise RuntimeError(f"{failure_context} failed: {detail}")
    return None


# ── Danger signal ───────────────────────────────────────────────────────────

def compute_danger_signal(
    rewards: np.ndarray,
    dones: np.ndarray,
    lookback: int = 5,
) -> np.ndarray:
    """Estimate per-timestep danger from reward anomalies and done density.

    Combines two complementary heuristics:

    1. **Reward anomaly** — steps where ``reward < mean − 0.5·std``
       receive +0.3 danger.
    2. **Done density** — a forward-looking sliding window of width
       *lookback* counts upcoming terminations; each done in the
       window contributes +0.5 danger.

    Parameters
    ----------
    rewards : ndarray, shape ``[T]``
        Per-step rewards within one episode.
    dones : ndarray, shape ``[T]``
        Binary done flags (values > 0.5 treated as True).
    lookback : int
        Window size for the done-density heuristic.

    Returns
    -------
    ndarray, shape ``[T]``
        Danger scores clipped to ``[0, 1]``.
    """
    rewards = _as_float32(np.asarray(rewards))
    dones = _as_float32(np.asarray(dones))
    T = int(rewards.shape[0])
    if T == 0:
        return np.zeros((0,), dtype=np.float32)

    danger = np.zeros(T, dtype=np.float32)

    # ── Heuristic 1: reward anomaly ─────────────────────────────────────
    r_std = float(rewards.std())
    if r_std > 1e-6:
        threshold = float(rewards.mean() - 0.5 * r_std)
        danger += (rewards < threshold).astype(np.float32) * 0.3

    # ── Heuristic 2: forward-looking done density ───────────────────────
    if lookback > 0:
        done01 = (dones > 0.5).astype(np.float32, copy=False)
        # Right-pad with zeros so the sliding window never underflows
        pad_len = max(lookback - 1, 0)
        done_padded = (
            np.concatenate([done01, np.zeros(pad_len, dtype=np.float32)])
            if pad_len > 0
            else done01
        )
        cumsum = np.cumsum(done_padded, dtype=np.float32)
        # c_shifted[i] = cumsum[i-1] for i ≥ 1, else 0
        c_shifted = np.concatenate(
            [np.zeros(1, dtype=np.float32), cumsum[: max(T - 1, 0)]]
        )
        # window_sum[i] = Σ done_padded[i : i+lookback]
        window_sum = cumsum[lookback - 1 : lookback - 1 + T] - c_shifted[:T]
        n = min(len(window_sum), T)
        danger[:n] += window_sum[:n] * 0.5

    return np.clip(danger, 0.0, 1.0).astype(np.float32, copy=False)


# ── Remaining-steps computation ─────────────────────────────────────────────

def compute_remaining_steps_vectorized(
    dones: np.ndarray,
    max_remaining: int = 100,
) -> np.ndarray:
    """Compute per-timestep distance to the nearest future done flag.

    Uses a reverse cumulative-minimum scan for O(T) complexity with no
    Python loops.

    Parameters
    ----------
    dones : ndarray, shape ``[T]``
        Binary done flags (values > 0.5 treated as True).
    max_remaining : int
        Upper cap on reported remaining steps.

    Returns
    -------
    ndarray, shape ``[T]``, dtype ``int32``
        ``remaining[t]`` = number of steps from ``t`` to the nearest done
        at or after ``t``, capped at *max_remaining*.  At done positions
        the value is 0.
    """
    dones = _as_float32(np.asarray(dones))
    T = int(dones.shape[0])
    if T == 0:
        return np.zeros((0,), dtype=np.int32)

    positions = np.arange(T, dtype=np.int32)
    sentinel = np.int32(T + max_remaining)

    # Mark done positions with their index; elsewhere use a large sentinel
    done_mask = dones > 0.5
    done_pos = np.where(done_mask, positions, sentinel).astype(np.int32)

    # Reverse cummin: for each position, find the nearest done *ahead*
    nearest_done = np.minimum.accumulate(done_pos[::-1])[::-1]
    remaining = np.clip(nearest_done - positions, 0, max_remaining)
    return remaining.astype(np.int32, copy=False)


def compute_remaining_steps_batch(
    dones_batch: np.ndarray,
    max_remaining: int = 100,
) -> np.ndarray:
    """Batched version of :func:`compute_remaining_steps_vectorized`.

    Parameters
    ----------
    dones_batch : ndarray, shape ``[B, T]``
    max_remaining : int

    Returns
    -------
    ndarray, shape ``[B, T]``, dtype ``int32``

    Raises
    ------
    ValueError
        If *dones_batch* is not 2-D.
    """
    dones_batch = _as_float32(np.asarray(dones_batch))
    if dones_batch.ndim != 2:
        raise ValueError(
            f"dones_batch must be 2D (B, T), got shape={dones_batch.shape}"
        )

    B, T = dones_batch.shape
    if T == 0:
        return np.zeros((B, 0), dtype=np.int32)

    positions = np.arange(T, dtype=np.int32)[None, :]  # (1, T) broadcast
    sentinel = np.int32(T + max_remaining)

    done_mask = dones_batch > 0.5
    done_pos = np.where(done_mask, positions, sentinel).astype(np.int32)

    nearest_done = np.minimum.accumulate(done_pos[:, ::-1], axis=1)[:, ::-1]
    remaining = np.clip(nearest_done - positions, 0, max_remaining)
    return remaining.astype(np.int32, copy=False)


def compute_remaining_steps_from_episode(
    ep_dones: np.ndarray,
    start: int,
    seq_len: int,
    ep_len: int,
    max_remaining: int = 100,
) -> np.ndarray:
    """Compute remaining steps for a contiguous slice of an episode.

    Extracts ``ep_dones[start : start + seq_len]`` and delegates to
    :func:`compute_remaining_steps_vectorized`.  If the slice is shorter
    than *seq_len* (near episode end), the output is right-padded with
    *max_remaining*.

    Parameters
    ----------
    ep_dones : ndarray
        Full episode done array (length ≥ *start*).
    start : int
        First index of the slice.
    seq_len : int
        Desired output length.
    ep_len : int
        Total episode length (used for documentation; bounds come from
        the array itself).
    max_remaining : int

    Returns
    -------
    ndarray, shape ``[seq_len]``, dtype ``int32``
    """
    end = min(start + seq_len, len(ep_dones))
    slice_dones = ep_dones[start:end]
    remaining = compute_remaining_steps_vectorized(slice_dones, max_remaining)
    # Right-pad if the slice was shorter than requested
    if len(remaining) < seq_len:
        pad = np.full(seq_len - len(remaining), max_remaining, dtype=np.int32)
        remaining = np.concatenate([remaining, pad])
    return remaining


def compute_discounted_returns_to_go(
    rewards: np.ndarray,
    dones: np.ndarray,
    gamma: float,
) -> np.ndarray:
    """Compute discounted Monte Carlo returns until the next done signal."""
    rewards_f = _as_float32(np.asarray(rewards)).reshape(-1)
    dones_f = _as_float32(np.asarray(dones)).reshape(-1)
    if rewards_f.shape != dones_f.shape:
        raise ValueError(
            f"rewards and dones must share shape, got {rewards_f.shape} vs {dones_f.shape}"
        )
    gamma_f = float(gamma)
    if not (0.0 <= gamma_f <= 1.0):
        raise ValueError(f"gamma must be within [0, 1], got {gamma_f}")

    returns = np.zeros_like(rewards_f, dtype=np.float32)
    running = 0.0
    for idx in range(rewards_f.shape[0] - 1, -1, -1):
        reward = float(rewards_f[idx])
        done = bool(dones_f[idx] > 0.5)
        if done:
            running = reward
        else:
            running = reward + gamma_f * running
        returns[idx] = running
    return returns


