_KNOWN_OPT_FIELDS = [
    "learning_rate", "weight_decay", "betas", "eps",
    "max_grad_norm", "use_grad_clip",
]

_KNOWN_RL_FIELDS = [
    "gamma", "gae_lambda",
    "value_loss_coef", "entropy_coef",
    "actor_entropy_scale", "actor_analytic_weight",
    "actor_reinforce_aux_weight_discrete",
    "imag_gradient", "imag_gradient_mix", "use_reward_ema",
]


def _config_data_from_object(config: Any) -> Dict[str, Any]:
    """Extract known training-config fields from an arbitrary object."""
    data: Dict[str, Any] = {}
    for name in _KNOWN_TOP_FIELDS:
        if hasattr(config, name):
            data[name] = getattr(config, name)

    opt: Dict[str, Any] = {}
    for name in _KNOWN_OPT_FIELDS:
        if hasattr(config, name):
            opt[name] = getattr(config, name)
    if opt:
        data["optimizer"] = opt

    rl: Dict[str, Any] = {}
    for name in _KNOWN_RL_FIELDS:
        if hasattr(config, name):
            rl[name] = getattr(config, name)
    if rl:
        data["rl"] = rl

    return data


def _normalize_training_config(config: Optional[Any]) -> TrainingConfig:
    """Convert any config-like input into a canonical ``TrainingConfig``.

    Accepts:
      - ``None``          → default config
      - ``TrainingConfig`` → returned as-is
      - ``TrainParams``   → ``.to_training_config()``
      - ``dict``          → ``TrainingConfig.from_dict(...)`` with canonical fields
      - arbitrary object  → field extraction → dict → ``from_dict``

    After conversion, the global activation-validation mode is updated
    to match ``config.validation_mode``.
    """
    if config is None:
        cfg = get_default_config()
        set_activation_validation_mode(cfg.validation_mode)
        return cfg

    if isinstance(config, TrainingConfig):
        set_activation_validation_mode(config.validation_mode)
        return config

    if isinstance(config, TrainParams):
        cfg = config.to_training_config()
        set_activation_validation_mode(cfg.validation_mode)
        return cfg

    data = dict(config) if isinstance(config, dict) else _config_data_from_object(config)
    cfg = TrainingConfig.from_dict(data)
    set_activation_validation_mode(cfg.validation_mode)
    return cfg


