# ══════════════════════════════════════════════════════════════════════════════
#  SECTION 3 ▸ DANGER-AWARE SAMPLING
# ══════════════════════════════════════════════════════════════════════════════
#
#  Depends on: SECTION 1 (_as_float32)
#
#  Public API
#  ──────────
#    register_danger_fn()          — register env-specific danger heuristic

#
#  Design note (v4.6 fix [FIX-REG])
#  ─────────────────────────────────
#    v4.5 hardcoded physics danger for four environments inside the class.
#    Now a module-level registry (_DANGER_FN_REGISTRY) is used.  Built-in
#    heuristics are registered at import time.  Users extend by calling
#    ``register_danger_fn("my_env", my_fn)`` before creating the sampler.
# ══════════════════════════════════════════════════════════════════════════════


# ── Danger function registry ────────────────────────────────────────────────

_DANGER_FN_REGISTRY: Dict[str, Callable[[np.ndarray], np.ndarray]] = {}


def register_danger_fn(
    env_type: str,
    fn: Callable[[np.ndarray], np.ndarray],
) -> None:
    """Register a danger heuristic for *env_type*.

    Parameters
    ----------
    env_type : str
        Case-insensitive environment identifier (e.g. ``"cartpole"``).
    fn : callable
        ``fn(states: ndarray[N, D]) -> ndarray[N]`` returning danger ∈ [0, 1].
    """
    _DANGER_FN_REGISTRY[env_type.lower()] = fn


# ── Built-in danger heuristics ──────────────────────────────────────────────

def _cartpole_danger(states: np.ndarray) -> np.ndarray:
    if states.shape[-1] < 4:
        return np.ones(len(states), dtype=np.float32) * 0.5
    x_danger = np.abs(states[..., 0]) / 2.4
    theta_danger = np.abs(states[..., 2]) / 0.21
    return np.clip(np.maximum(x_danger, theta_danger), 0, 1).astype(np.float32)


def _mountaincar_danger(states: np.ndarray) -> np.ndarray:
    if states.shape[-1] < 2:
        return np.ones(len(states), dtype=np.float32) * 0.5
    position = states[..., 0]
    return np.clip(1.0 - (position + 0.5), 0, 1).astype(np.float32)


def _pendulum_danger(states: np.ndarray) -> np.ndarray:
    if states.shape[-1] < 3:
        return np.ones(len(states), dtype=np.float32) * 0.5
    cos_theta = states[..., 0]
    return np.clip((1 - cos_theta) / 2, 0, 1).astype(np.float32)


def _acrobot_danger(states: np.ndarray) -> np.ndarray:
    if states.shape[-1] < 4:
        return np.ones(len(states), dtype=np.float32) * 0.5
    cos_theta1 = states[..., 0]
    return np.clip((1 - cos_theta1) / 2, 0, 1).astype(np.float32)


register_danger_fn("cartpole", _cartpole_danger)
register_danger_fn("mountaincar", _mountaincar_danger)
register_danger_fn("pendulum", _pendulum_danger)
register_danger_fn("acrobot", _acrobot_danger)


# ══════════════════════════════════════════════════════════════════════════════
#  END OF SECTION 3
