# ══════════════════════════════════════════════════════════════════════════════
#  SECTION 4 ▸ REPLAY BUFFER
# ══════════════════════════════════════════════════════════════════════════════
#
#  Depends on: SECTION 1 (compute_danger_signal, compute_remaining_steps_*,
#                         _as_float32, _moving_mean_1d)
#              SECTION 3 (ReplayBuffer)
#
#  Public API
#  ──────────
#    ReplayBuffer   — episode-based experience replay
#
#  Critical fix: [BUG-1.1]
#  ────────────────────────
#    v4.5 had obs-filling code OUTSIDE the per-sample loop in both
#    ``sample_sequences`` and ``sample_sequences_weighted``, causing all
#    but the last sample to contain uninitialised memory.  This is now
#    fixed by delegating to ``_fill_obs_slice`` which is called INSIDE
#    the loop.
# ══════════════════════════════════════════════════════════════════════════════


class ReplayBuffer:
    """Episode-based replay buffer with danger-weighted sampling.

    Episodes are stored as complete numpy arrays.  The temporal contract is::

        len(vitals) == len(actions) + 1
                    == len(rewards) + 1
                    == len(dones) + 1

    where ``vitals[0]`` is the initial observation and ``vitals[t+1]`` is
    the observation resulting from ``actions[t]``.

    Parameters
    ----------
    capacity : int
        Maximum number of episodes.  Oldest episodes are discarded on
        overflow.
    store_obs : bool
        Whether to store raw observations alongside vitals.
    auto_compute_remaining : bool
        If True, remaining-step counts are pre-computed at episode
        finalisation.
    """

    def __init__(
        self,
        capacity: int = 100000,
        store_obs: bool = True,
        auto_compute_remaining: bool = False,
    ):
        self.episodes: List[Dict[str, np.ndarray]] = []
        self.capacity = capacity
        self.store_obs = store_obs
        self.auto_compute_remaining = auto_compute_remaining

        self.current: Optional[Dict[str, List]] = None
        self._episode_counter = 0
        self._state_schema_version = 2

    # ── Basic properties ────────────────────────────────────────────────

    def __len__(self) -> int:
        return len(self.episodes)

    def total_steps(self) -> int:
        """Total number of vitals frames across all stored episodes."""
        return sum(len(ep["vitals"]) for ep in self.episodes)

    # ── Episode construction ────────────────────────────────────────────

    def start_episode(
        self,
        initial_vitals: Optional[np.ndarray] = None,
        initial_obs: Optional[Any] = None,
    ):
        """Begin accumulating a new episode.

        Optionally provide the initial observation via *initial_vitals*
        (and *initial_obs* if ``store_obs`` is True).
        """
        self.current = {
            "obs": [] if self.store_obs else None,
            "vitals": [],
            "actions": [],
            "rewards": [],
            "dones": [],
            "terminated": [],
            "truncated": [],
            "log_probs": [],
        }
        if initial_vitals is not None:
            self.add_initial(vitals=initial_vitals, obs=initial_obs)

    def add_initial(
        self,
        vitals: np.ndarray,
        obs: Optional[Any] = None,
    ) -> None:
        """Record the initial observation of an episode.

        Must be called exactly once before any ``add_step`` call.
        """
        if self.current is None:
            self.start_episode()

        v_list = self.current["vitals"]
        if len(v_list) == 0:
            v_list.append(np.asarray(vitals, dtype=np.float32))

        if self.store_obs and self.current["obs"] is not None:
            o_list = self.current["obs"]
            if len(o_list) == 0:
                if isinstance(obs, dict):
                    o_list.append(
                        {k: np.asarray(v, dtype=np.float32) for k, v in obs.items()}
                    )
                elif obs is not None:
                    o_list.append(np.asarray(obs, dtype=np.float32))
                else:
                    o_list.append(None)

    def add_step(
        self,
        vitals: np.ndarray,
        action: np.ndarray,
        reward: float,
        done: bool,
        terminated: Optional[bool] = None,
        truncated: Optional[bool] = None,
        obs: Optional[Any] = None,
        log_prob: float = 0.0,
    ):
        """Append one transition to the current episode.

        *vitals* is the observation **after** taking *action* (i.e. the
        next-state).  The buffer stores ``[s_0, s_1, …, s_T]`` in
        ``vitals`` and ``[a_0, …, a_{T-1}]`` in ``actions``.
        """
        if self.current is None:
            self.start_episode()

        if len(self.current["vitals"]) == 0:
            raise ValueError(
                "No initial vitals recorded. Call start_episode(initial_vitals=…) "
                "or add_initial(vitals=…) before add_step(…)."
            )

        if terminated is None:
            terminated = bool(done)
        if truncated is None:
            truncated = False

        self.current["vitals"].append(np.asarray(vitals, dtype=np.float32))
        self.current["actions"].append(np.asarray(action, dtype=np.float32))
        self.current["rewards"].append(float(reward))
        self.current["dones"].append(float(done))
        self.current["terminated"].append(float(terminated))
        self.current["truncated"].append(float(truncated))
        self.current["log_probs"].append(float(log_prob))

        if self.store_obs and self.current["obs"] is not None:
            if isinstance(obs, dict):
                self.current["obs"].append(
                    {k: np.asarray(v, dtype=np.float32) for k, v in obs.items()}
                )
            elif obs is not None:
                self.current["obs"].append(np.asarray(obs, dtype=np.float32))
            else:
                self.current["obs"].append(None)

        if done:
            self.finish_episode()

    def add_transition(
        self,
        action: np.ndarray,
        reward: float,
        done: bool,
        next_vitals: np.ndarray,
        terminated: Optional[bool] = None,
        truncated: Optional[bool] = None,
        obs: Optional[Any] = None,
        log_prob: float = 0.0,
    ) -> None:
        """Alias for ``add_step`` with parameter names matching (s, a, r, s')."""
        self.add_step(
            vitals=next_vitals,
            action=action,
            reward=reward,
            done=done,
            terminated=terminated,
            truncated=truncated,
            obs=obs,
            log_prob=log_prob,
        )

    def finish_episode(self) -> Optional[int]:
        """Finalise the current episode, compute derived fields, and store.

        Returns the episode index, or ``None`` if the episode was empty.
        """
        if self.current is None:
            return None

        cur = self.current
        vitals_len = len(cur["vitals"])
        actions_len = len(cur["actions"])
        rewards_len = len(cur["rewards"])
        dones_len = len(cur["dones"])
        term_len = len(cur["terminated"])
        trunc_len = len(cur["truncated"])
        logp_len = len(cur["log_probs"])

        if vitals_len == 0:
            self.current = None
            return None

        # ── Temporal contract validation ────────────────────────────────
        if not (
            vitals_len == actions_len + 1
            and actions_len == rewards_len == dones_len
            == term_len == trunc_len == logp_len
        ):
            raise ValueError(
                "ReplayBuffer temporal contract violation.\n"
                f"  vitals={vitals_len}  actions={actions_len}  rewards={rewards_len}\n"
                f"  dones={dones_len}  terminated={term_len}  truncated={trunc_len}\n"
                f"  log_probs={logp_len}\n"
                "Expected: vitals = actions+1 = rewards+1 = dones+1 = …"
            )

        # ── Build episode dict ──────────────────────────────────────────
        episode: Dict[str, Any] = {
            "vitals": np.stack(cur["vitals"]),
            "actions": np.stack(cur["actions"]),
            "rewards": np.array(cur["rewards"], dtype=np.float32),
            "dones": np.array(cur["dones"], dtype=np.float32),
            "terminated": np.array(cur["terminated"], dtype=np.float32),
            "truncated": np.array(cur["truncated"], dtype=np.float32),
            "log_probs": np.array(cur["log_probs"], dtype=np.float32),
        }
        ep_len = vitals_len  # number of vitals frames

        # ── Obs stacking ───────────────────────────────────────────────
        if self.store_obs and cur["obs"] is not None:
            obs_list = cur["obs"]
            if len(obs_list) == ep_len and all(o is not None for o in obs_list):
                if isinstance(obs_list[0], dict):
                    keys = list(obs_list[0].keys())
                    episode["obs"] = {
                        k: np.stack([o[k] for o in obs_list]) for k in keys
                    }
                else:
                    episode["obs"] = np.stack(obs_list)
            elif len(obs_list) != ep_len:
                logger.debug(
                    f"Episode obs length ({len(obs_list)}) != vitals length "
                    f"({ep_len}); obs not stored for this episode."
                )

        # ── Done source (union of terminated + truncated) ───────────────
        dones_src = np.maximum(
            episode["terminated"], episode["truncated"]
        ).astype(np.float32)
        episode["dones_src"] = dones_src

        step_danger = compute_danger_signal(
            rewards=episode["rewards"],
            dones=episode["dones"],
            lookback=5,
        )  # shape (actions_len,)
        # Prepend 0 for the initial state (no danger info at t=0)
        danger = np.concatenate(
            [np.zeros(1, dtype=np.float32), _as_float32(step_danger)]
        )

        # Ensure danger aligns with vitals (ep_len,)
        if danger.shape[0] != ep_len:
            aligned = np.zeros(ep_len, dtype=np.float32)
            n = min(ep_len, danger.shape[0])
            aligned[:n] = danger[:n]
            danger = aligned
        episode["danger"] = danger

        # ── Remaining steps ─────────────────────────────────────────────
        if self.auto_compute_remaining:
            episode["remaining_steps"] = compute_remaining_steps_vectorized(
                dones_src, max_remaining=100
            )

        # ── Metadata ────────────────────────────────────────────────────
        episode["idx"] = self._episode_counter
        episode["length"] = ep_len
        self._episode_counter += 1

        self.episodes.append(episode)

        # Evict oldest episodes on overflow
        excess = len(self.episodes) - self.capacity
        if excess > 0:
            del self.episodes[:excess]

        ep_idx = episode["idx"]
        self.current = None
        return ep_idx

    # ── Internal: done source ───────────────────────────────────────────

    def _get_done_src(self, ep: Dict[str, np.ndarray]) -> np.ndarray:
        """Return the canonical done signal for *ep*.

        Prefers the cached ``dones_src`` field (computed in
        ``finish_episode``), falling back to ``terminated ∨ truncated``
        or ``dones``.
        """
        if "dones_src" in ep:
            return _as_float32(ep["dones_src"])
        if "terminated" in ep and "truncated" in ep:
            return np.maximum(
                _as_float32(ep["terminated"]),
                _as_float32(ep["truncated"]),
            )
        if "terminated" in ep:
            return _as_float32(ep["terminated"])
        return _as_float32(ep["dones"])

    # ── Internal: obs helpers (BUG-1.1 fix) ─────────────────────────────

    def _init_obs_output(
        self,
        ep0: Dict[str, np.ndarray],
        batch_size: int,
        seq_len: int,
        include_obs: bool,
    ) -> Tuple[Optional[Union[np.ndarray, Dict[str, np.ndarray]]], bool]:
        """Allocate obs output arrays from *ep0*'s format.

        Returns ``(obs_out_or_None, is_dict)``.
        """
        if not include_obs or not self.store_obs or "obs" not in ep0:
            return None, False

        T_out = seq_len + 1
        if isinstance(ep0["obs"], dict):
            out = {
                k: np.empty(
                    (batch_size, T_out) + v.shape[1:], dtype=v.dtype
                )
                for k, v in ep0["obs"].items()
            }
            return out, True

        out = np.empty(
            (batch_size, T_out) + ep0["obs"].shape[1:],
            dtype=ep0["obs"].dtype,
        )
        return out, False

    def _fill_obs_slice(
        self,
        obs_out: Optional[Union[np.ndarray, Dict[str, np.ndarray]]],
        obs_is_dict: bool,
        idx: int,
        ep: Dict[str, np.ndarray],
        start: int,
        end: int,
    ) -> None:
        """Fill ``obs_out[idx]`` from *ep*.  **Must be called inside the
        per-sample loop** — this is the structural fix for BUG-1.1."""
        if obs_out is None:
            return
        if "obs" not in ep:
            if obs_is_dict:
                for arr in obs_out.values():
                    arr[idx] = 0
            else:
                obs_out[idx] = 0
            return
        if obs_is_dict:
            for k, arr in obs_out.items():
                arr[idx] = ep["obs"][k][start:end]
        else:
            obs_out[idx] = ep["obs"][start:end]

    # ── Internal: episode / start-point selection ───────────────────────

    def _get_valid_episodes(
        self, seq_len: int
    ) -> Tuple[Optional[List[Dict[str, np.ndarray]]], int]:
        """Return episodes long enough for *seq_len*, possibly reducing it.

        Returns ``(valid_episodes_or_None, effective_seq_len)``.
        """
        required = seq_len + 1
        valid = [ep for ep in self.episodes if len(ep["vitals"]) >= required]
        if valid:
            return valid, seq_len

        if not self.episodes:
            return None, seq_len

        max_len = max(len(ep["vitals"]) for ep in self.episodes)
        if max_len < 2:
            return None, seq_len

        seq_len = min(seq_len, max_len - 1)
        required = seq_len + 1
        valid = [ep for ep in self.episodes if len(ep["vitals"]) >= required]
        return (valid or None), seq_len

    def _select_uniform(
        self,
        valid_episodes: List[Dict],
        batch_size: int,
        required_ep_len: int,
    ) -> List[Tuple[int, int]]:
        """Uniformly sample ``(episode_idx, start)`` pairs."""
        chosen_eps = np.random.choice(
            len(valid_episodes), batch_size, replace=True
        )
        selections = []
        for ep_idx in chosen_eps:
            ep = valid_episodes[int(ep_idx)]
            max_start = len(ep["vitals"]) - required_ep_len
            start = int(np.random.randint(0, max_start + 1))
            selections.append((int(ep_idx), start))
        return selections

    def _build_weighted_points(
        self,
        valid_episodes: List[Dict[str, np.ndarray]],
        seq_len: int,
        required_ep_len: int,
    ) -> Optional[Tuple[np.ndarray, np.ndarray, np.ndarray]]:
        """Enumerate every valid ``(episode, start)`` and its mean danger.

        Returns ``(ep_ids[P], starts[P], mean_dangers[P])`` or ``None``.
        """
        all_ep_ids: List[np.ndarray] = []
        all_starts: List[np.ndarray] = []
        all_dangers: List[np.ndarray] = []

        for ep_idx, ep in enumerate(valid_episodes):
            ep_len = len(ep["vitals"])
            n_points = ep_len - required_ep_len + 1
            if n_points <= 0:
                continue

            danger = _as_float32(
                ep.get(
                    "danger",
                    np.ones(ep_len, dtype=np.float32) * 0.5,
                )
            )
            # Keep danger aligned with sequence windows: danger[0] is usually
            # a bootstrap placeholder for initial vitals, not a transition.
            if danger.shape[0] == ep_len and ep_len > 1:
                danger = np.concatenate([danger[1:], danger[-1:]])
            means = _moving_mean_1d(danger, window=required_ep_len)[:n_points]

            all_ep_ids.append(np.full(n_points, ep_idx, dtype=np.int32))
            all_starts.append(np.arange(n_points, dtype=np.int32))
            all_dangers.append(means.astype(np.float32, copy=False))

        if not all_ep_ids:
            return None
        return (
            np.concatenate(all_ep_ids),
            np.concatenate(all_starts),
            np.concatenate(all_dangers),
        )

    # ── Internal: batch assembly ────────────────────────────────────────

    def _build_sample_batch(
        self,
        valid_episodes: List[Dict[str, np.ndarray]],
        selections: List[Tuple[int, int]],
        seq_len: int,
        include_obs: bool,
        importance_weights: np.ndarray,
    ) -> Dict[str, np.ndarray]:
        """Assemble output arrays from ``(ep_idx, start)`` selections.

        This is the **single** code path for filling vitals / actions /
        rewards / dones / obs.  By design, ``_fill_obs_slice`` is
        invoked inside the per-sample loop, which structurally prevents
        the BUG-1.1 regression.
        """
        batch_size = len(selections)
        ep0 = valid_episodes[selections[0][0]]
        v_shape = ep0["vitals"].shape[1:]
        a_shape = ep0["actions"].shape[1:]

        vitals = np.empty((batch_size, seq_len + 1) + v_shape, dtype=np.float32)
        actions = np.empty((batch_size, seq_len) + a_shape, dtype=np.float32)
        rewards = np.empty((batch_size, seq_len), dtype=np.float32)
        dones = np.empty((batch_size, seq_len), dtype=np.float32)
        logp = np.empty((batch_size, seq_len), dtype=np.float32)
        danger_targets = np.empty(
            (batch_size, seq_len + 1, 1), dtype=np.float32
        )

        obs_out, obs_is_dict = self._init_obs_output(
            ep0, batch_size, seq_len, include_obs
        )

        for i, (ep_idx, start) in enumerate(selections):
            ep = valid_episodes[ep_idx]
            end_v = start + seq_len + 1
            end_a = start + seq_len

            vitals[i] = ep["vitals"][start:end_v]
            actions[i] = ep["actions"][start:end_a]
            rewards[i] = ep["rewards"][start:end_a]
            dones[i] = self._get_done_src(ep)[start:end_a]
            logp[i] = ep["log_probs"][start:end_a]

            if "danger" in ep:
                danger_targets[i, :, 0] = ep["danger"][start:end_v]
            else:
                danger_targets[i, :, 0] = 0.0

            # [BUG-1.1 FIX] obs filled INSIDE the loop
            self._fill_obs_slice(
                obs_out, obs_is_dict, i, ep, start, end_v
            )

        result: Dict[str, np.ndarray] = {
            "vitals": vitals,
            "actions": actions,
            "rewards": rewards,
            "dones": dones,
            "log_probs": logp,
            "danger_targets": danger_targets,
            "importance_weights": np.asarray(
                importance_weights, dtype=np.float32
            ),
        }
        if obs_out is not None:
            result["obs"] = obs_out
        return result

    # ── Public sampling API ─────────────────────────────────────────────

    def sample_sequences(
        self,
        batch_size: int,
        seq_len: int,
        include_obs: bool = False,
    ) -> Optional[Dict[str, np.ndarray]]:
        """Sample *batch_size* sub-sequences uniformly at random.

        Returns a dict with keys ``vitals (B, T+1, D)``,
        ``actions (B, T, A)``, ``rewards (B, T)``, ``dones (B, T)``,
        ``log_probs (B, T)``, ``danger_targets (B, T+1, 1)``,
        ``importance_weights (B,)`` — or ``None`` if the buffer is empty.
        """
        valid, seq_len = self._get_valid_episodes(seq_len)
        if valid is None:
            return None
        required = seq_len + 1
        selections = self._select_uniform(valid, batch_size, required)
        iw = np.ones(batch_size, dtype=np.float32)
        return self._build_sample_batch(valid, selections, seq_len, include_obs, iw)

    def sample_subsequences(
        self,
        batch_size: int,
        subseq_len: int = 64,
        include_obs: bool = False,
    ) -> Optional[Dict[str, np.ndarray]]:
        """Sample *batch_size* contiguous sub-sequences for WM BPTT training.

        Each sub-sequence is drawn from a single episode, preserving
        temporal continuity.  Episodes shorter than ``subseq_len + 1``
        are skipped.  The method delegates to the existing
        ``_select_uniform`` / ``_build_sample_batch`` helpers.

        Returns
        -------
        dict or None
            Same schema as :meth:`sample_sequences` —
            ``vitals (B, L+1, D)``, ``actions (B, L, A)``,
            ``rewards (B, L)``, ``dones (B, L)`` — or ``None``
            if no episode is long enough.
        """
        valid, subseq_len = self._get_valid_episodes(subseq_len)
        if valid is None:
            return None
        required = subseq_len + 1
        selections = self._select_uniform(valid, batch_size, required)
        iw = np.ones(batch_size, dtype=np.float32)
        return self._build_sample_batch(valid, selections, subseq_len, include_obs, iw)


    def sample_sequences_with_remaining(
        self,
        batch_size: int,
        seq_len: int,
        include_obs: bool = False,

        max_remaining: int = 100,
    ) -> Optional[Dict[str, np.ndarray]]:
        """Sample sub-sequences with additional ``remaining_steps`` field.

        Extends the base sampling methods with per-timestep remaining-step
        counts, episode lengths, and step indices — needed by the *will*
        module for horizon-aware training.
        """
        valid, seq_len = self._get_valid_episodes(seq_len)
        if valid is None:
            return None

        required = seq_len + 1
        valid_episode_ids = [
            idx
            for idx, ep in enumerate(self.episodes)
            if len(ep["vitals"]) >= required
        ]
        selections = self._select_uniform(valid, batch_size, required)

        ep0 = valid[selections[0][0]]
        v_shape = ep0["vitals"].shape[1:]
        a_shape = ep0["actions"].shape[1:]

        vitals = np.empty((batch_size, seq_len + 1) + v_shape, dtype=np.float32)
        actions = np.empty((batch_size, seq_len) + a_shape, dtype=np.float32)
        rewards = np.empty((batch_size, seq_len), dtype=np.float32)
        dones = np.empty((batch_size, seq_len), dtype=np.float32)
        logp = np.empty((batch_size, seq_len), dtype=np.float32)
        remaining = np.empty((batch_size, seq_len), dtype=np.int32)
        ep_lens = np.empty(batch_size, dtype=np.int32)
        episode_ids = np.empty(batch_size, dtype=np.int32)
        step_idx = np.empty((batch_size, seq_len), dtype=np.int32)

        obs_out, obs_is_dict = self._init_obs_output(
            ep0, batch_size, seq_len, include_obs
        )

        for i, (ep_idx, start) in enumerate(selections):
            ep = valid[ep_idx]
            absolute_ep_idx = valid_episode_ids[ep_idx]
            ep_len = len(ep["vitals"])
            end_v = start + seq_len + 1
            end_a = start + seq_len

            vitals[i] = ep["vitals"][start:end_v]
            actions[i] = ep["actions"][start:end_a]
            rewards[i] = ep["rewards"][start:end_a]
            dones_src = self._get_done_src(ep)
            dones[i] = dones_src[start:end_a]
            logp[i] = ep["log_probs"][start:end_a]

            if "remaining_steps" in ep:
                remaining[i] = ep["remaining_steps"][start:end_a]
            else:
                remaining[i] = compute_remaining_steps_from_episode(
                    dones_src, start, seq_len, ep_len, max_remaining
                )

            ep_lens[i] = ep_len
            episode_ids[i] = absolute_ep_idx
            step_idx[i] = np.arange(start, end_a, dtype=np.int32)

            # [BUG-1.1 FIX]
            self._fill_obs_slice(obs_out, obs_is_dict, i, ep, start, end_v)

        result: Dict[str, np.ndarray] = {
            "vitals": vitals,
            "actions": actions,
            "rewards": rewards,
            "dones": dones,
            "log_probs": logp,
            "remaining_steps": remaining,
            "episode_lengths": ep_lens,
            "episode_ids": episode_ids,
            "step_indices": step_idx,
        }
        if obs_out is not None:
            result["obs"] = obs_out
        return result

    def sample_initial_states(
        self,
        batch_size: int,
        init_seq_len: int = 10,
    ) -> Optional[Dict[str, np.ndarray]]:
        """Sample short observation–action prefixes (for imagination seeds).

        Returns ``{"vitals": (B, L, D), "actions": (B, L-1, A)}``
        or ``None``.
        """
        valid = [
            ep for ep in self.episodes
            if len(ep["vitals"]) >= init_seq_len
        ]
        if not valid:
            return None

        chosen = np.random.choice(len(valid), batch_size, replace=True)
        vitals_list, actions_list = [], []
        for idx in chosen:
            ep = valid[int(idx)]
            ep_len = len(ep["vitals"])
            start = int(np.random.randint(0, ep_len - init_seq_len + 1))
            end = start + init_seq_len
            vitals_list.append(ep["vitals"][start:end])
            actions_list.append(ep["actions"][start : end - 1])
        return {
            "vitals": np.stack(vitals_list),
            "actions": np.stack(actions_list),
        }

    # ── Query helpers ───────────────────────────────────────────────────

    def get_new_completed_episodes(
        self, last_seen_idx: int
    ) -> List[Dict[str, np.ndarray]]:
        """Return episodes whose index exceeds *last_seen_idx*."""
        return [ep for ep in self.episodes if ep.get("idx", -1) > last_seen_idx]

    def get_all_returns(self) -> List[float]:
        return [float(ep["rewards"].sum()) for ep in self.episodes]

    def get_recent_returns(self, n: int = 10) -> List[float]:
        recent = self.episodes[-n:] if len(self.episodes) >= n else self.episodes
        return [float(ep["rewards"].sum()) for ep in recent]

    def get_statistics(self) -> Dict[str, float]:
        """Aggregate buffer statistics."""
        if not self.episodes:
            return {
                "n_episodes": 0,
                "total_steps": 0,
                "avg_episode_length": 0.0,
                "avg_return": 0.0,
            }

        total = self.total_steps()
        returns = self.get_all_returns()
        stats: Dict[str, float] = {
            "n_episodes": len(self.episodes),
            "total_steps": total,
            "avg_episode_length": total / len(self.episodes),
            "avg_return": float(np.mean(returns)),
            "min_return": float(np.min(returns)),
            "max_return": float(np.max(returns)),
        }



        if self.auto_compute_remaining:
            rem_arrays = [
                ep["remaining_steps"]
                for ep in self.episodes
                if "remaining_steps" in ep
            ]
            if rem_arrays:
                all_rem = np.concatenate(rem_arrays)
                stats["remaining_mean"] = float(np.mean(all_rem))
                stats["remaining_max"] = float(np.max(all_rem))
                stats["zero_remaining_ratio"] = float(np.mean(all_rem == 0))

        return stats



    def verify_remaining_steps(self, sample_size: int = 100) -> Dict[str, Any]:
        """Spot-check remaining-step correctness."""
        if not self.episodes:
            return {"status": "NO_DATA"}

        issues: List[str] = []
        for ep in self.episodes[:sample_size]:
            if "remaining_steps" not in ep:
                continue
            rem = ep["remaining_steps"]
            dones = self._get_done_src(ep)
            done_mask = dones > 0.5
            if done_mask.any() and (rem[done_mask] != 0).any():
                issues.append("remaining at done should be 0")
            if (rem < 0).any():
                issues.append("remaining contains negative values")

        return {
            "valid": len(issues) == 0,
            "issues": list(set(issues)),
            "checked_episodes": min(sample_size, len(self.episodes)),
        }

    # ── Lifecycle ───────────────────────────────────────────────────────

    def clear(self):
        """Discard all episodes and reset the accumulator."""
        self.episodes.clear()
        self.current = None

    def state_dict(self) -> Dict[str, Any]:
        """Serialise buffer contents for checkpointing."""
        state: Dict[str, Any] = {
            "schema_version": self._state_schema_version,
            "episodes": self._checkpoint_safe_value(self.episodes),
            "current": self._checkpoint_safe_value(self.current),
            "capacity": self.capacity,
            "store_obs": self.store_obs,
            "episode_counter": self._episode_counter,
            "auto_compute_remaining": self.auto_compute_remaining,
        }

        return state

    @staticmethod
    def _checkpoint_safe_value(value: Any) -> Any:
        if isinstance(value, dict):
            return {
                key: ReplayBuffer._checkpoint_safe_value(item)
                for key, item in value.items()
            }
        if isinstance(value, list):
            return [ReplayBuffer._checkpoint_safe_value(item) for item in value]
        if isinstance(value, tuple):
            return tuple(ReplayBuffer._checkpoint_safe_value(item) for item in value)
        if isinstance(value, np.ndarray):
            if value.dtype.hasobject or value.dtype.kind not in {"?", "b", "i", "u", "f", "c"}:
                raise TypeError(
                    "ReplayBuffer checkpoint payload only supports numeric or boolean numpy arrays."
                )
            return torch.from_numpy(np.array(value, copy=True))
        if isinstance(value, np.generic):
            return value.item()
        return copy.deepcopy(value)

    @staticmethod
    def _checkpoint_array_to_numpy(
        value: Any,
        *,
        dtype: Optional[Any] = None,
    ) -> np.ndarray:
        if isinstance(value, torch.Tensor):
            array = value.detach().cpu().numpy()
        else:
            array = np.asarray(value)
        if dtype is not None:
            array = np.asarray(array, dtype=dtype)
        return array

    @staticmethod
    def _normalize_loaded_scalar_list(value: Any) -> list[float]:
        if value is None:
            return []
        if isinstance(value, list):
            items = value
        else:
            items = list(value)
        normalized: list[float] = []
        for item in items:
            array = ReplayBuffer._checkpoint_array_to_numpy(item, dtype=np.float32).reshape(-1)
            if array.size != 1:
                raise TypeError("ReplayBuffer scalar checkpoint payload must contain scalar values.")
            normalized.append(float(array[0]))
        return normalized

    @staticmethod
    def _normalize_loaded_array_list(value: Any) -> list[np.ndarray]:
        if value is None:
            return []
        if isinstance(value, list):
            items = value
        else:
            items = list(value)
        return [
            ReplayBuffer._checkpoint_array_to_numpy(item, dtype=np.float32)
            for item in items
        ]

    @staticmethod
    def _normalize_loaded_obs_list(value: Any) -> list[Any]:
        if value is None:
            return []
        if isinstance(value, list):
            items = value
        else:
            items = list(value)
        return [
            ReplayBuffer._normalize_obs_payload(item)
            if item is not None
            else None
            for item in items
        ]

    @staticmethod
    def _normalize_obs_payload(obs: Any) -> Any:
        if isinstance(obs, dict):
            return {
                str(k): ReplayBuffer._checkpoint_array_to_numpy(v, dtype=np.float32)
                for k, v in obs.items()
            }
        if obs is None:
            return None
        return ReplayBuffer._checkpoint_array_to_numpy(obs, dtype=np.float32)

    @staticmethod
    def _align_vitals_danger(
        danger: np.ndarray,
        *,
        vitals_len: int,
    ) -> np.ndarray:
        aligned = np.zeros(vitals_len, dtype=np.float32)
        n = min(vitals_len, int(danger.shape[0]))
        if n > 0:
            aligned[:n] = danger[:n]
        return aligned

    def _normalize_loaded_episode(
        self,
        episode: Any,
        *,
        fallback_idx: int,
        auto_compute_remaining: bool,
    ) -> Dict[str, Any]:
        if not isinstance(episode, dict):
            raise TypeError("ReplayBuffer episode payload must be a mapping.")

        vitals = self._checkpoint_array_to_numpy(episode.get("vitals", []), dtype=np.float32)
        actions = self._checkpoint_array_to_numpy(episode.get("actions", []), dtype=np.float32)
        rewards = self._checkpoint_array_to_numpy(
            episode.get("rewards", []),
            dtype=np.float32,
        ).reshape(-1)
        dones = self._checkpoint_array_to_numpy(
            episode.get("dones", []),
            dtype=np.float32,
        ).reshape(-1)
        terminated = self._checkpoint_array_to_numpy(
            episode.get("terminated", episode.get("dones", [])),
            dtype=np.float32,
        ).reshape(-1)
        truncated = self._checkpoint_array_to_numpy(
            episode.get("truncated", np.zeros_like(dones)),
            dtype=np.float32,
        ).reshape(-1)
        log_probs = self._checkpoint_array_to_numpy(
            episode.get("log_probs", np.zeros_like(rewards)),
            dtype=np.float32,
        ).reshape(-1)

        vitals_len = int(vitals.shape[0]) if vitals.ndim > 0 else 0
        actions_len = int(actions.shape[0]) if actions.ndim > 0 else 0
        rewards_len = int(rewards.shape[0])
        dones_len = int(dones.shape[0])
        terminated_len = int(terminated.shape[0])
        truncated_len = int(truncated.shape[0])
        log_probs_len = int(log_probs.shape[0])
        if not (
            vitals_len == actions_len + 1
            and actions_len == rewards_len == dones_len
            == terminated_len == truncated_len == log_probs_len
        ):
            raise ValueError(
                "ReplayBuffer checkpoint payload violates temporal contract."
            )

        dones_src = np.maximum(terminated, truncated).astype(np.float32)
        danger_raw = episode.get("danger")
        if danger_raw is None:
            step_danger = compute_danger_signal(
                rewards=rewards,
                dones=dones,
                lookback=5,
            )
            danger = np.concatenate(
                [np.zeros(1, dtype=np.float32), _as_float32(step_danger)]
            )
        else:
            danger = self._checkpoint_array_to_numpy(
                danger_raw,
                dtype=np.float32,
            ).reshape(-1)
        danger = self._align_vitals_danger(danger, vitals_len=vitals_len)

        normalized_episode: Dict[str, Any] = {
            "vitals": vitals,
            "actions": actions,
            "rewards": rewards,
            "dones": dones,
            "terminated": terminated,
            "truncated": truncated,
            "log_probs": log_probs,
            "dones_src": dones_src,
            "danger": danger,
            "idx": int(episode.get("idx", fallback_idx)),
            "length": int(episode.get("length", vitals_len)),
        }
        if "obs" in episode:
            normalized_obs = self._normalize_obs_payload(episode.get("obs"))
            if normalized_obs is not None:
                normalized_episode["obs"] = normalized_obs

        remaining_raw = episode.get("remaining_steps")
        if remaining_raw is not None:
            normalized_episode["remaining_steps"] = self._checkpoint_array_to_numpy(
                remaining_raw,
                dtype=np.float32,
            ).reshape(-1)
        elif auto_compute_remaining:
            normalized_episode["remaining_steps"] = compute_remaining_steps_vectorized(
                dones_src,
                max_remaining=100,
            )
        return normalized_episode

    @staticmethod
    def _normalize_loaded_current(current: Any) -> Optional[Dict[str, Any]]:
        if current is None:
            return None
        if not isinstance(current, dict):
            raise TypeError("ReplayBuffer current episode payload must be a mapping or None.")
        normalized: Dict[str, Any] = {
            "obs": None,
            "vitals": [],
            "actions": [],
            "rewards": [],
            "dones": [],
            "terminated": [],
            "truncated": [],
            "log_probs": [],
        }
        normalized["obs"] = ReplayBuffer._normalize_loaded_obs_list(current.get("obs"))
        for key in ("vitals", "actions"):
            normalized[key] = ReplayBuffer._normalize_loaded_array_list(current.get(key))
        for key in ("rewards", "dones", "terminated", "truncated", "log_probs"):
            normalized[key] = ReplayBuffer._normalize_loaded_scalar_list(current.get(key))
        if not normalized["terminated"] and normalized["dones"]:
            normalized["terminated"] = list(normalized["dones"])
        if not normalized["truncated"] and normalized["dones"]:
            normalized["truncated"] = [0.0] * len(normalized["dones"])
        if not normalized["log_probs"] and normalized["actions"]:
            normalized["log_probs"] = [0.0] * len(normalized["actions"])
        return normalized

    def load_state_dict(self, state: Dict[str, Any]):
        """Restore buffer contents from a checkpoint."""
        if not isinstance(state, dict):
            raise TypeError("ReplayBuffer state payload must be a mapping.")
        self.capacity = int(state.get("capacity", self.capacity))
        self.store_obs = bool(state.get("store_obs", self.store_obs))
        self.auto_compute_remaining = bool(
            state.get("auto_compute_remaining", self.auto_compute_remaining)
        )
        self._state_schema_version = int(state.get("schema_version", 1))
        episodes_raw = state.get("episodes", [])
        if not isinstance(episodes_raw, list):
            raise TypeError("ReplayBuffer episodes payload must be a list.")
        migrated_episodes = [
            self._normalize_loaded_episode(
                episode,
                fallback_idx=idx,
                auto_compute_remaining=self.auto_compute_remaining,
            )
            for idx, episode in enumerate(episodes_raw)
        ]
        self.episodes = migrated_episodes
        self.current = self._normalize_loaded_current(state.get("current"))
        explicit_counter = state.get("episode_counter")
        if explicit_counter is None:
            self._episode_counter = (
                max((int(ep.get("idx", -1)) for ep in self.episodes), default=-1) + 1
            )
        else:
            self._episode_counter = int(explicit_counter)
        self._state_schema_version = 2



# ══════════════════════════════════════════════════════════════════════════════
#  SECTION 5 ▸ ROLLOUT BUFFER (PPO)
# ══════════════════════════════════════════════════════════════════════════════
#
#  Depends on: (standalone — numpy + torch only)
#
#  Public API
#  ──────────
#    RolloutData    — dataclass holding one minibatch
#    RolloutBuffer  — fixed-size ring buffer with GAE computation
#
#  Note: This buffer is designed for **single-environment** on-policy
#  collection (PPO-style).  For multi-env vectorised collection, wrap
#  multiple RolloutBuffers or extend with a batch dimension.
# ══════════════════════════════════════════════════════════════════════════════


@dataclass
class RolloutData:
    """A minibatch extracted from :class:`RolloutBuffer`."""
    observations: np.ndarray
    actions: np.ndarray
    old_log_probs: np.ndarray
    advantages: np.ndarray
    returns: np.ndarray
    old_values: np.ndarray


class RolloutBuffer:
    """Fixed-size on-policy buffer with GAE advantage computation.

    Collects ``(obs, action, reward, done, value, log_prob)`` tuples
    from a single environment, then computes GAE advantages and
    returns in-place via :meth:`compute_returns_and_advantages`.

    Parameters
    ----------
    buffer_size : int
        Maximum number of transitions.
    obs_dim : int
        Observation / feature dimensionality.
    action_dim : int
        Action dimensionality (continuous) or number of classes (discrete).
    gamma : float
        Discount factor.
    gae_lambda : float
        GAE λ parameter.
    device : torch.device, optional
        Target device for tensors yielded by :meth:`get_batches`.
    """

    def __init__(
        self,
        buffer_size: int = 2048,
        obs_dim: int = 640,
        action_dim: int = 32,
        gamma: float = 0.99,
        gae_lambda: float = 0.95,
        device: Optional[torch.device] = None,
    ):
        self.buffer_size = buffer_size
        self.obs_dim = obs_dim
        self.action_dim = action_dim
        self.gamma = gamma
        self.gae_lambda = gae_lambda
        self.device = device or torch.device("cpu")

        # Pre-allocated storage
        self.observations = np.zeros((buffer_size, obs_dim), dtype=np.float32)
        self.actions = np.zeros((buffer_size, action_dim), dtype=np.float32)
        self.rewards = np.zeros(buffer_size, dtype=np.float32)
        self.dones = np.zeros(buffer_size, dtype=np.float32)
        self.values = np.zeros(buffer_size, dtype=np.float32)
        self.log_probs = np.zeros(buffer_size, dtype=np.float32)

        self.advantages = np.zeros(buffer_size, dtype=np.float32)
        self.returns = np.zeros(buffer_size, dtype=np.float32)

        self.pos = 0
        self.full = False
        self._ready = False

    def __len__(self) -> int:
        return self.buffer_size if self.full else self.pos

    def reset(self):
        """Clear the buffer for a new collection cycle."""
        self.pos = 0
        self.full = False
        self._ready = False

    def add(
        self,
        observation: np.ndarray,
        action: np.ndarray,
        reward: float,
        done: bool,
        value: float,
        log_prob: float,
    ):
        """Append a single transition."""
        self.observations[self.pos] = observation
        self.actions[self.pos] = action
        self.rewards[self.pos] = reward
        self.dones[self.pos] = float(done)
        self.values[self.pos] = value
        self.log_probs[self.pos] = log_prob

        self.pos += 1
        if self.pos >= self.buffer_size:
            self.full = True
            self.pos = 0

    def compute_returns_and_advantages(
        self,
        last_value: float = 0.0,
        last_done: bool = True,
    ):
        """Compute GAE advantages and discounted returns in-place.

        Must be called **after** filling the buffer and **before**
        iterating with :meth:`get_batches`.

        Parameters
        ----------
        last_value : float
            Bootstrap value for the state following the last stored
            transition.  Should be 0 if the episode ended, otherwise
            the critic's estimate of V(s_{T+1}).
        last_done : bool
            Whether the last stored transition was terminal.
        """
        size = len(self)
        last_gae = 0.0

        for t in reversed(range(size)):
            if t == size - 1:
                next_non_terminal = 1.0 - float(last_done)
                next_value = last_value
            else:
                next_non_terminal = 1.0 - self.dones[t]
                next_value = self.values[t + 1]

            delta = (
                self.rewards[t]
                + self.gamma * next_value * next_non_terminal
                - self.values[t]
            )
            last_gae = delta + self.gamma * self.gae_lambda * next_non_terminal * last_gae
            self.advantages[t] = last_gae
            self.returns[t] = last_gae + self.values[t]

        self._ready = True

    def get_batches(
        self,
        batch_size: int,
        shuffle: bool = True,
    ) -> Iterator[Dict[str, Tensor]]:
        """Yield minibatch dicts of tensors on ``self.device``.

        Raises ``RuntimeError`` if advantages have not been computed.
        """
        if not self._ready:
            raise RuntimeError(
                "Call compute_returns_and_advantages() before get_batches()"
            )

        size = len(self)
        indices = np.arange(size)
        if shuffle:
            np.random.shuffle(indices)

        for start in range(0, size, batch_size):
            end = min(start + batch_size, size)
            bi = indices[start:end]
            yield {
                "observations": torch.from_numpy(self.observations[bi]).to(self.device),
                "actions": torch.from_numpy(self.actions[bi]).to(self.device),
                "log_probs": torch.from_numpy(self.log_probs[bi]).to(self.device),
                "advantages": torch.from_numpy(self.advantages[bi]).to(self.device),
                "returns": torch.from_numpy(self.returns[bi]).to(self.device),
                "values": torch.from_numpy(self.values[bi]).to(self.device),
            }

    def get_all(self) -> Dict[str, Tensor]:
        """Return the full buffer as a single dict of tensors."""
        if not self._ready:
            raise RuntimeError(
                "Call compute_returns_and_advantages() before get_all()"
            )
        size = len(self)
        return {
            "observations": torch.from_numpy(self.observations[:size]).to(self.device),
            "actions": torch.from_numpy(self.actions[:size]).to(self.device),
            "log_probs": torch.from_numpy(self.log_probs[:size]).to(self.device),
            "advantages": torch.from_numpy(self.advantages[:size]).to(self.device),
            "returns": torch.from_numpy(self.returns[:size]).to(self.device),
            "values": torch.from_numpy(self.values[:size]).to(self.device),
        }


# ══════════════════════════════════════════════════════════════════════════════
#  END OF SECTION 5
# ══════════════════════════════════════════════════════════════════════════════


# ══════════════════════════════════════════════════════════════════════════════
#  SECTION 6 ▸ LOSS FUNCTIONS
# ══════════════════════════════════════════════════════════════════════════════
#
#  Depends on: SECTION 1 (_get_zero_tensor, extract_real_value)
#              external  (aletheia_foundation.symexp)
#
#  Public API
#  ──────────

#    compute_value_loss()            — Huber with optional PPO-clip
#    compute_entropy_from_distribution() — entropy from a Distribution obj
#    compute_entropy_protection_loss()   — penalty when entropy too low
#    compute_alpha_loss()            — SAC-style adaptive α
#    compute_gae()                   — recursive GAE (the SOLE implementation)
#
#  Private API (used by SECTION 8)
#  ────────────────────────────────
#    _compute_rl_losses()            — aggregate all RL losses
#
#  Design notes
#  ────────────
#    [BUG-2.1] compute_entropy_loss (v4.5) accepted an ambiguous log_probs
#              tensor.  Replaced by compute_entropy_from_distribution()
#              which takes a torch.distributions.Distribution and calls
#              .entropy() directly — no shape guesswork.
#
#    [BUG-2.3] target_entropy for discrete actions is now POSITIVE
#              (0.1 * log(A)), not -log(A).  A warning is emitted if
#              both entropy_protection and adaptive_alpha are enabled.
#
#    [BUG-2.5] compute_gae_vectorized (v4.5) used per-batch Python loops
#              and pow() that overflows for long segments.  REMOVED.
#              The recursive compute_gae() is the sole implementation.
# ══════════════════════════════════════════════════════════════════════════════





def compute_value_loss(
    values: Tensor,
    target_values: Tensor,
    old_values: Optional[Tensor] = None,
    clip_epsilon: float = 0.2,
    use_clipping: bool = True,
    huber_delta: float = 1.0,
) -> Tensor:
    """Critic loss with optional PPO-style value clipping.

    Parameters
    ----------
    values : Tensor, shape ``[N]``
        Current critic predictions.
    target_values : Tensor, shape ``[N]``
        Discounted returns (targets).
    old_values : Tensor, shape ``[N]``, optional
        Previous critic predictions (for clipping).
    clip_epsilon : float
    use_clipping : bool
    huber_delta : float
        Transition point for Smooth-L1 / Huber loss.

    Returns
    -------
    Tensor (scalar)
    """
    if use_clipping and old_values is not None:
        values_clipped = old_values + torch.clamp(
            values - old_values, -clip_epsilon, clip_epsilon
        )
        loss_unclipped = F.smooth_l1_loss(values, target_values, beta=huber_delta)
        loss_clipped = F.smooth_l1_loss(values_clipped, target_values, beta=huber_delta)
        return torch.max(loss_unclipped, loss_clipped)

    return F.smooth_l1_loss(values, target_values, beta=huber_delta)


def compute_entropy_from_distribution(
    dist: Any,
) -> Tensor:
    """Compute mean entropy from a ``torch.distributions.Distribution``.

    This replaces the v4.5 ``compute_entropy_loss(log_probs, probs)``
    which had ambiguous input semantics (BUG-2.1).

    Parameters
    ----------
    dist :
        Any object with an ``.entropy()`` method returning a tensor
        whose last dimension (if > 0-D) is summed (multi-dim actions).

    Returns
    -------
    Tensor (scalar)
        Mean entropy across the batch.
    """
    ent = dist.entropy()
    if ent.dim() > 1:
        ent = ent.sum(dim=-1)
    return ent.mean()


def compute_entropy_protection_loss(
    entropy: Tensor,
    threshold: float = 0.5,
    strength: float = 0.1,
) -> Tensor:
    """Quadratic penalty when mean entropy drops below *threshold*.

    Parameters
    ----------
    entropy : Tensor (scalar or per-sample)
    threshold : float
    strength : float

    Returns
    -------
    Tensor (scalar)
    """
    deficit = torch.clamp(threshold - entropy, min=0.0)
    return strength * deficit.pow(2).mean()


def compute_alpha_loss(
    log_alpha: Tensor,
    entropy: Tensor,
    target_entropy: float,
) -> Tensor:
    """SAC-style adaptive temperature loss.

    Minimising this drives ``alpha`` so that the policy entropy
    matches *target_entropy*.

    Parameters
    ----------
    log_alpha : Tensor (scalar, requires_grad)
    entropy : Tensor (scalar or per-sample, detached internally)
    target_entropy : float

    Returns
    -------
    Tensor (scalar)
    """
    return (log_alpha * (target_entropy - entropy).detach()).mean()


def compute_gae(
    rewards: Tensor,
    values: Tensor,
    dones: Tensor,
    gamma: float = 0.99,
    gae_lambda: float = 0.95,
    discounts: Optional[Tensor] = None,
) -> Tuple[Tensor, Tensor]:
    """Generalised Advantage Estimation (recursive, numerically stable).

    This is the **sole** GAE implementation in the codebase. The retired
    v4.5 vectorized variant used ``pow()``, overflowed on long segments,
    and its Python loops offered no speed benefit over the simple
    recursion below.

    Parameters
    ----------
    rewards : Tensor, shape ``[B, T]``
    values : Tensor, shape ``[B, T+1]``
        ``values[:, -1]`` is the bootstrap value.
    dones : Tensor, shape ``[B, T]``
    gamma : float
    gae_lambda : float
    discounts : Tensor, shape ``[B, T]``, optional
        [v5.5] Per-step discount factors (e.g. ``gamma * continue_prob``).
        When provided, overrides ``gamma * (1 - dones)``.

    Returns
    -------
    advantages : Tensor, shape ``[B, T]``
    returns : Tensor, shape ``[B, T]``
    """
    B, T = rewards.shape
    advantages = torch.zeros_like(rewards)
    last_gae = torch.zeros(B, device=rewards.device, dtype=rewards.dtype)

    for t in reversed(range(T)):
        if discounts is not None:
            disc_t = discounts[:, t]  # [v5.5] DreamerV3 soft discount
        else:
            disc_t = gamma * (1.0 - dones[:, t])
        delta = rewards[:, t] + disc_t * values[:, t + 1] - values[:, t]
        last_gae = delta + disc_t * gae_lambda * last_gae
        advantages[:, t] = last_gae

    returns = advantages + values[:, :-1]
    return advantages, returns


# ── [v5.5 T5+T6] DreamerV3 Actor Loss ─────────────────────────────────────


class RewardEMA:
    """Dreamer-style running quantile normalizer (P5/P95 EMA)."""

    def __init__(
        self,
        device: Optional[torch.device] = None,
        alpha: float = 1e-2,
        q_low: float = 0.05,
        q_high: float = 0.95,
    ):
        self.device = device or torch.device("cpu")
        self.alpha = float(alpha)
        self.range = torch.tensor([q_low, q_high], device=self.device)

    def __call__(self, x: Tensor, ema_vals: Tensor) -> Tuple[Tensor, Tensor]:
        flat_x = torch.flatten(x.detach()).float()
        x_quantile = torch.quantile(flat_x, self.range)
        ema_vals[:] = self.alpha * x_quantile + (1.0 - self.alpha) * ema_vals
        scale = torch.clamp(ema_vals[1] - ema_vals[0], min=1.0)
        offset = ema_vals[0]
        return offset.detach(), scale.detach()


def compute_dreamer_actor_loss(
    log_probs: Tensor,
    target: Tensor,
    base: Tensor,
    weights: Tensor,
    entropy: Tensor,
    imag_gradient: str = "dynamics",
    imag_gradient_mix: float = 0.0,
    entropy_scale: float = 3e-4,
    use_reward_ema: bool = True,
    use_advantage_normalization: bool = False,
    actor_analytic_weight: float = 1.0,
    actor_reinforce_aux_weight_discrete: float = 0.1,
    is_discrete_action: bool = False,
    reward_ema: Optional["RewardEMA"] = None,
    reward_ema_vals: Optional[Tensor] = None,
    analytic_scale_mask: Optional[Tensor] = None,
    corridor_semantic_blend_beta: Optional[Tensor] = None,
    corridor_semantic_advantage_term_clamp_scale: float = 0.0,
    corridor_semantic_advantage_term_clamp_min: float = 0.0,
) -> Tuple[Tensor, Dict[str, float]]:
    """Dreamer-style actor objective with gradient-mode selection."""
    if reward_ema is None:
        reward_ema = RewardEMA(device=target.device)
    if reward_ema_vals is None:
        reward_ema_vals = torch.zeros((2,), device=target.device)

    raw_adv = target - base
    if use_reward_ema:
        offset, scale = reward_ema(target, reward_ema_vals)
        normed_target = (target - offset) / scale
        normed_base = (base - offset) / scale
        adv = normed_target - normed_base
    else:
        normed_target = target
        normed_base = base
        adv = raw_adv

    if use_advantage_normalization:
        adv = normalize_tensor(adv)
        reinforce_adv = normalize_tensor(raw_adv.detach())
    else:
        reinforce_adv = adv.detach()

    corridor_semantic_blend_beta_t = None
    if corridor_semantic_blend_beta is not None:
        corridor_semantic_blend_beta_t = corridor_semantic_blend_beta.to(
            device=target.device,
            dtype=target.dtype,
        )
        if (
            corridor_semantic_blend_beta_t.shape != target.shape
            and corridor_semantic_blend_beta_t.numel() == target.numel()
        ):
            corridor_semantic_blend_beta_t = corridor_semantic_blend_beta_t.reshape_as(
                target
            )
        if corridor_semantic_blend_beta_t.shape != target.shape:
            corridor_semantic_blend_beta_t = None
    if corridor_semantic_blend_beta_t is None:
        corridor_semantic_blend_beta_t = torch.zeros_like(target)
    else:
        corridor_semantic_blend_beta_t = corridor_semantic_blend_beta_t.clamp(0.0, 1.0)

    corridor_adv_term = normed_target - normed_base
    corridor_adv_term_clamp = max(
        0.0, float(corridor_semantic_advantage_term_clamp_min)
    )
    clamp_scale = max(0.0, float(corridor_semantic_advantage_term_clamp_scale))
    if clamp_scale > 0.0:
        corridor_adv_term_clamp = max(
            corridor_adv_term_clamp,
            clamp_scale * float(normed_target.detach().abs().mean().item()),
        )
    if corridor_adv_term_clamp > 0.0:
        corridor_adv_term = corridor_adv_term.clamp(min=-corridor_adv_term_clamp)
    analytic_term = torch.lerp(
        normed_target,
        corridor_adv_term,
        corridor_semantic_blend_beta_t,
    )
    analytic_scale_mask_t = None
    if analytic_scale_mask is not None:
        analytic_scale_mask_t = analytic_scale_mask.to(device=target.device, dtype=analytic_term.dtype)
        if analytic_scale_mask_t.shape != analytic_term.shape and analytic_scale_mask_t.numel() == analytic_term.numel():
            analytic_scale_mask_t = analytic_scale_mask_t.reshape_as(analytic_term)
        if analytic_scale_mask_t.shape != analytic_term.shape:
            analytic_scale_mask_t = None
    if analytic_scale_mask_t is None:
        analytic_term_scaled = analytic_term
        analytic_scale_mask_t = torch.ones_like(analytic_term)
    else:
        analytic_term_scaled = analytic_term * analytic_scale_mask_t
    reinforce_term = log_probs * reinforce_adv
    mode = str(imag_gradient).lower()
    analytic_coef = 0.0
    reinforce_coef = 0.0
    mix = 0.0
    if mode == "dynamics":
        analytic_coef = float(actor_analytic_weight)
    elif mode == "reinforce":
        reinforce_coef = 1.0
    elif mode == "both":
        mix = float(imag_gradient_mix)
        analytic_coef = float(actor_analytic_weight) * mix
        reinforce_coef = 1.0 - mix
    else:
        raise ValueError(f"Unsupported imag_gradient mode: {imag_gradient}")

    discrete_aux_coef = 0.0
    if bool(is_discrete_action) and analytic_coef > 0.0:
        discrete_aux_coef = float(actor_reinforce_aux_weight_discrete)
        reinforce_coef += discrete_aux_coef

    actor_target = analytic_coef * analytic_term_scaled + reinforce_coef * reinforce_term
    actor_loss = -(weights * actor_target).mean()
    entropy_loss = -float(entropy_scale) * entropy.mean()
    total = actor_loss + entropy_loss

    flat_t = target.detach().reshape(-1).float()
    flat_w = weights.detach().reshape(-1).float()
    weighted_analytic = weights.detach() * (analytic_coef * analytic_term_scaled.detach())
    weighted_reinforce = weights.detach() * (reinforce_coef * reinforce_term.detach())
    metrics: Dict[str, float] = {
        "loss_actor_dreamer": actor_loss.item(),
        "loss_entropy": entropy_loss.item(),
        "imag_gradient_mode": mode,
        "target_mean": flat_t.mean().item(),
        "target_std": flat_t.std(unbiased=False).item(),
        "target_p05": torch.quantile(flat_t, 0.05).item(),
        "target_p95": torch.quantile(flat_t, 0.95).item(),
        "actor_weights_mean": flat_w.mean().item(),
        "actor_weights_min": flat_w.min().item(),
        "actor_weights_max": flat_w.max().item(),
        "normed_target_mean": normed_target.detach().mean().item(),
        "normed_target_std": normed_target.detach().std(unbiased=False).item(),
        "adv_mean": adv.detach().mean().item(),
        "adv_std": adv.detach().std(unbiased=False).item(),
        "raw_adv_mean": raw_adv.detach().mean().item(),
        "raw_adv_std": raw_adv.detach().std(unbiased=False).item(),
        "analytic_term_mean": analytic_term.detach().mean().item(),
        "analytic_term_scaled_mean": analytic_term_scaled.detach().mean().item(),
        "analytic_scale_mask_mean": analytic_scale_mask_t.detach().mean().item(),
        "analytic_scale_mask_active_fraction": (analytic_scale_mask_t.detach() < 0.999999).float().mean().item(),
        "corridor_semantic_blend_mean": corridor_semantic_blend_beta_t.detach().mean().item(),
        "corridor_semantic_blend_active_fraction": (corridor_semantic_blend_beta_t.detach() > 0.0).float().mean().item(),
        "corridor_semantic_adv_term_mean": corridor_adv_term.detach().mean().item(),
        "corridor_semantic_blended_term_mean": analytic_term.detach().mean().item(),
        "corridor_semantic_adv_term_clamp": float(corridor_adv_term_clamp),
        "reinforce_term_mean": reinforce_term.detach().mean().item(),
        "weighted_analytic_term_mean": weighted_analytic.mean().item(),
        "weighted_reinforce_term_mean": weighted_reinforce.mean().item(),
        "weighted_actor_target_mean": (weighted_analytic + weighted_reinforce).mean().item(),
        "actor_analytic_coef": float(analytic_coef),
        "actor_reinforce_coef": float(reinforce_coef),
        "actor_reinforce_aux_applied": float(discrete_aux_coef),
        "is_discrete_action": float(bool(is_discrete_action)),
    }
    if target.dim() >= 2 and target.shape[1] > 0:
        split = max(1, target.shape[1] // 2)
        head = slice(0, split)
        tail = slice(split, target.shape[1])
        metrics.update({
            "raw_adv_head_mean": raw_adv.detach()[:, head].mean().item(),
            "raw_adv_tail_mean": raw_adv.detach()[:, tail].mean().item() if split < target.shape[1] else raw_adv.detach()[:, head].mean().item(),
            "weight_head_mean": weights.detach()[:, head].mean().item(),
            "weight_tail_mean": weights.detach()[:, tail].mean().item() if split < target.shape[1] else weights.detach()[:, head].mean().item(),
            "analytic_scale_mask_head_mean": analytic_scale_mask_t.detach()[:, head].mean().item(),
            "analytic_scale_mask_tail_mean": analytic_scale_mask_t.detach()[:, tail].mean().item() if split < target.shape[1] else analytic_scale_mask_t.detach()[:, head].mean().item(),
            "weighted_analytic_head_mean": weighted_analytic[:, head].mean().item(),
            "weighted_analytic_tail_mean": weighted_analytic[:, tail].mean().item() if split < target.shape[1] else weighted_analytic[:, head].mean().item(),
            "weighted_reinforce_head_mean": weighted_reinforce[:, head].mean().item(),
            "weighted_reinforce_tail_mean": weighted_reinforce[:, tail].mean().item() if split < target.shape[1] else weighted_reinforce[:, head].mean().item(),
        })
    if mode == "both":
        metrics["imag_gradient_mix"] = float(imag_gradient_mix)
    return total, metrics


def _masked_mean_tensor(values: Tensor, mask: Optional[Tensor]) -> Tensor:
    if mask is None:
        return values.mean()
    mask_t = mask.to(device=values.device, dtype=values.dtype)
    if mask_t.shape != values.shape and mask_t.numel() == values.numel():
        mask_t = mask_t.reshape_as(values)
    if mask_t.shape != values.shape:
        return values.mean()
    denom = mask_t.sum()
    if float(denom.detach().item()) <= 0.0:
        return torch.zeros((), device=values.device, dtype=values.dtype)
    return (values * mask_t).sum() / denom


def _resolve_distribution_probs_and_log_probs(
    dist: Any,
) -> Tuple[Optional[Tensor], Optional[Tensor]]:
    probs = getattr(dist, "probs", None)
    log_probs = getattr(dist, "log_probs", None)
    logits = getattr(dist, "logits", None)

    if probs is None and logits is not None:
        probs = torch.softmax(logits, dim=-1)
    if log_probs is None:
        if probs is not None:
            log_probs = torch.log(probs.clamp(min=1e-8))
        elif logits is not None:
            log_probs = torch.log_softmax(logits, dim=-1)

    return probs, log_probs


def _compute_distribution_kl_tensor(
    anchor_dist: Any,
    current_dist: Any,
) -> Optional[Tensor]:
    anchor_probs, anchor_log_probs = _resolve_distribution_probs_and_log_probs(
        anchor_dist
    )
    _, current_log_probs = _resolve_distribution_probs_and_log_probs(current_dist)

    if anchor_probs is not None and anchor_log_probs is not None and current_log_probs is not None:
        return (
            anchor_probs.detach()
            * (anchor_log_probs.detach() - current_log_probs)
        ).sum(dim=-1)

    kl_fn = getattr(anchor_dist, "kl_divergence", None)
    if callable(kl_fn):
        try:
            kl = kl_fn(current_dist)
            if isinstance(kl, Tensor):
                return kl
        except Exception:
            return None
    return None


_REAL_STABILITY_CORRIDOR_KL_THRESHOLD = 0.05


def _compute_policy_bank_min_kl_tensor(
    current_actor: Any,
    anchor_actors: Optional[List[Any]],
    feat_t: Optional[Tensor],
) -> Tuple[Optional[Tensor], int]:
    if current_actor is None or not callable(current_actor):
        return None, 0
    if not isinstance(feat_t, Tensor) or feat_t.numel() <= 0:
        return None, 0
    valid_actors = [
        actor
        for actor in list(anchor_actors or [])
        if actor is not None and callable(actor)
    ]
    if not valid_actors:
        return None, 0
    try:
        with torch.no_grad():
            current_dist = current_actor(feat_t)
            kl_candidates: List[Tensor] = []
            for anchor_actor in valid_actors:
                anchor_dist = anchor_actor(feat_t)
                kl_flat = _compute_distribution_kl_tensor(anchor_dist, current_dist)
                if isinstance(kl_flat, Tensor) and kl_flat.numel() == feat_t.shape[0]:
                    kl_candidates.append(kl_flat.detach())
    except Exception:
        return None, 0
    if not kl_candidates:
        return None, 0
    return torch.stack(kl_candidates, dim=-1).min(dim=-1).values, len(kl_candidates)


