# ══════════════════════════════════════════════════════════════════════════════
#  SECTION 7 ▸ POLICY & OPTIMIZER UTILITIES
# ══════════════════════════════════════════════════════════════════════════════
#
#  Depends on: SECTION 1 (extract_real_value, _get_zero_tensor)
#              SECTION 6 (compute_gae)
#
#  Public API
#  ──────────
#    OptimizerBundle              — separate optimizers for WM / RL / alpha
#    compute_policy_outputs()     — model → (log_probs, values, entropy, dist)
#
#  Private API (used by SECTION 8)
#  ────────────────────────────────
#    _prepare_batch_data()        — move dict of tensors to device
#    _update_with_optimizer()     — zero_grad → backward → clip → step
#
#  Critical fix: [BUG-1.2]
#  ────────────────────────
#    v4.5 used a SINGLE optimizer for world-model AND policy, causing
#    Adam momentum corruption (zero-gradient steps on inactive params).
#    OptimizerBundle now holds independent optimizers for each module.
# ══════════════════════════════════════════════════════════════════════════════


class OptimizerBundle:
    """Independent optimizers for world-model, RL, and alpha.

    Prevents the Adam momentum pollution that occurs when a single
    optimizer's ``.step()`` is called with zero gradients on parameters
    that were not part of the current backward pass (BUG-1.2).

    Parameters
    ----------
    wm_optimizer : Optimizer, optional
        For world-model parameters.
    rl_optimizer : Optimizer
        For actor + critic parameters.
    alpha_optimizer : Optimizer, optional
        For the ``log_alpha`` temperature variable.
    wm_grad_clip : float
        Max gradient norm for world-model.
    rl_grad_clip : float
        Max gradient norm for RL (actor + critic).
    alpha_grad_clip : float
        Max gradient norm for alpha.
    """

    def __init__(
        self,
        rl_optimizer: Optional[torch.optim.Optimizer] = None,
        wm_optimizer: Optional[torch.optim.Optimizer] = None,
        actor_optimizer: Optional[torch.optim.Optimizer] = None,
        critic_optimizer: Optional[torch.optim.Optimizer] = None,
        alpha_optimizer: Optional[torch.optim.Optimizer] = None,
        wm_grad_clip: float = 1.0,
        rl_grad_clip: float = 1.0,
        actor_grad_clip: float = 1.0,
        critic_grad_clip: float = 1.0,
        alpha_grad_clip: float = 1.0,
    ):
        if rl_optimizer is None and actor_optimizer is None and critic_optimizer is None:
            raise ValueError("OptimizerBundle requires rl_optimizer or actor/critic optimizers.")
        self.wm_optimizer = wm_optimizer
        self.rl_optimizer = rl_optimizer
        self.actor_optimizer = actor_optimizer
        self.critic_optimizer = critic_optimizer
        self.alpha_optimizer = alpha_optimizer
        self.wm_grad_clip = wm_grad_clip
        self.rl_grad_clip = rl_grad_clip
        self.actor_grad_clip = actor_grad_clip
        self.critic_grad_clip = critic_grad_clip
        self.alpha_grad_clip = alpha_grad_clip

    def state_dict(self) -> Dict[str, Any]:
        """Serialise all optimizer states."""
        sd: Dict[str, Any] = {}
        if self.rl_optimizer is not None:
            sd["rl"] = self.rl_optimizer.state_dict()
        if self.wm_optimizer is not None:
            sd["wm"] = self.wm_optimizer.state_dict()
        if self.actor_optimizer is not None:
            sd["actor"] = self.actor_optimizer.state_dict()
        if self.critic_optimizer is not None:
            sd["critic"] = self.critic_optimizer.state_dict()
        if self.alpha_optimizer is not None:
            sd["alpha"] = self.alpha_optimizer.state_dict()
        return sd

    def load_state_dict(
        self,
        sd: Dict[str, Any],
        *,
        restore_mode: str = "strict",
    ) -> Dict[str, Any]:
        """Restore optimizer states from a checkpoint."""
        restore_mode = str(restore_mode or "strict").strip().lower()
        if restore_mode not in {"strict", "compatible", "skip"}:
            raise ValueError(
                "restore_mode must be one of ['strict', 'compatible', 'skip']."
            )

        report: Dict[str, Any] = {
            "restored": [],
            "skipped": [],
            "issues": [],
        }
        if restore_mode == "skip":
            return report

        for key, optimizer in (
            ("rl", self.rl_optimizer),
            ("wm", self.wm_optimizer),
            ("actor", self.actor_optimizer),
            ("critic", self.critic_optimizer),
            ("alpha", self.alpha_optimizer),
        ):
            if key not in sd or optimizer is None:
                continue
            try:
                optimizer.load_state_dict(sd[key])
            except (RuntimeError, ValueError) as exc:
                if restore_mode != "compatible":
                    raise
                report["skipped"].append(key)
                report["issues"].append(
                    {
                        "optimizer": key,
                        "message": str(exc),
                        "exception_type": type(exc).__name__,
                    }
                )
                continue
            report["restored"].append(key)
        return report


def _prepare_batch_data(
    batch: Dict[str, Any],
    device: torch.device,
) -> Dict[str, Any]:
    """Move all tensor values in *batch* to *device*."""
    return {
        k: v.to(device) if isinstance(v, torch.Tensor) else v
        for k, v in batch.items()
    }


def _update_with_optimizer(
    optimizer: torch.optim.Optimizer,
    loss: Tensor,
    max_grad_norm: float = 1.0,
) -> float:
    """``zero_grad → backward → clip_grad_norm → step``.

    Returns the (pre-clip) gradient norm.
    """
    optimizer.zero_grad()
    if not isinstance(loss, torch.Tensor) or not loss.requires_grad:
        return 0.0
    loss.backward()
    params = [p for g in optimizer.param_groups for p in g["params"] if p.grad is not None]
    if not params:
        optimizer.step()
        return 0.0
    grad_norm = torch.nn.utils.clip_grad_norm_(params, max_grad_norm).item()
    optimizer.step()
    return grad_norm


def compute_policy_outputs(
    model: nn.Module,
    vitals: Tensor,
    actions: Tensor,
    temperature: float = 1.0,
    intent: Optional[Tensor] = None,
) -> Tuple[Tensor, Tensor, Tensor, Any]:
    """Forward pass through an actor-critic model.

    Handles both 2-D ``(B, D)`` and 3-D ``(B, T, D)`` inputs by
    flattening and un-flattening automatically.

    Parameters
    ----------
    model : nn.Module
        Must be callable as ``model(vitals_flat, temperature=...,
        intent=...)`` returning ``(distribution, value_output)``.
    vitals : Tensor, shape ``(B, D)`` or ``(B, T, D)``
    actions : Tensor, shape ``(B, A)`` or ``(B, T, A)``
    temperature : float
    intent : Tensor, optional

    Returns
    -------
    log_probs : Tensor, shape ``(B,)`` or ``(B, T)``
    values : Tensor, same shape as log_probs
    entropy : Tensor, same shape as log_probs
    dist : Distribution
        The raw distribution object (for callers that need .sample()).
    """
    is_3d = vitals.dim() == 3
    if is_3d:
        B, T, D = vitals.shape
        vitals_flat = vitals.reshape(B * T, D)
        actions_flat = actions.reshape(B * T, -1)
    else:
        vitals_flat = vitals
        actions_flat = actions
        B, T = vitals.shape[0], 1

    dist, value_out = model(vitals_flat, temperature=temperature, intent=intent)
    values = extract_real_value(value_out)

    log_probs = dist.log_prob(actions_flat)
    if log_probs.dim() > 1:
        log_probs = log_probs.sum(dim=-1)

    entropy = dist.entropy()
    if entropy.dim() > 1:
        entropy = entropy.sum(dim=-1)

    if is_3d:
        log_probs = log_probs.view(B, T)
        entropy = entropy.view(B, T)
        values = values.view(B, T) if values.dim() >= 1 else values.unsqueeze(0).expand(B, T)

    return log_probs, values, entropy, dist


# ══════════════════════════════════════════════════════════════════════════════
#  END OF SECTION 7
