# ══════════════════════════════════════════════════════════════════════════════
#  SECTION 9 ▸ IMAGINATION ENGINE
# ══════════════════════════════════════════════════════════════════════════════
#
#  Depends on: SECTION 1 (extract_real_value, symexp)
#              SECTION 7 (compute_policy_outputs)
#
#  Public API
#  ──────────
#    ImaginationEngine  — world-model-based trajectory imagination
#
#  Critical fixes (v4.6.1)
#  ───────────────────────
#    [BUG-9.1] wm_state update: _step_world_model now RETURNS the new
#              wm_state so the caller can reassign it.  The old code used
#              wm_state.__dict__.update(...) which does NOT rebind the
#              caller's variable — all subsequent steps used stale state.
#    [BUG-9.2] Reward symexp: r_pred from the reward head is typically
#              in symlog space.  Now converted to real space via symexp()
#              before storing in the rollout.
#    [BUG-2.4] Continue-head truncation (carried over from v4.6).
# ══════════════════════════════════════════════════════════════════════════════


class ImaginationEngine:
    """Generate synthetic rollouts using a world model.

    Parameters
    ----------
    model : nn.Module
        Actor-critic model (used for policy and value queries).
    device : torch.device
    max_horizon : int
        Upper cap on imagination horizon.
    reward_clip : float
        Clamp imagined rewards to ``[-reward_clip, reward_clip]`` to
        prevent extreme values from an inaccurate world model.
    continue_threshold : float
        If the continue-head predicts a continuation probability below
        this threshold, the imagined trajectory is truncated at that step.
    symlog_clip : float
        Maximum absolute value for symexp conversion of predicted rewards.
    """

    def __init__(
        self,
        model: nn.Module,
        device: torch.device,
        max_horizon: int = 10,
        reward_clip: float = 10.0,
        continue_threshold: float = 0.5,
        hard_truncate: bool = False,
        symlog_clip: float = 30.0,
    ):
        self.model = model
        self.device = device
        self.max_horizon = max_horizon
        self.reward_clip = reward_clip
        self.continue_threshold = continue_threshold
        self.hard_truncate = hard_truncate
        self.symlog_clip = symlog_clip
        self.gae_lambda: float = 0.95  # [v5.5 T4] λ-return lambda
        self._gamma_buf: float = 0.99  # [v5.5 T4] updated by TrainingLoop

    # ── Internal helpers ────────────────────────────────────────────────

    def _get_world_model(self) -> Optional[nn.Module]:
        wm = getattr(self.model, "world_model", None)
        if wm is not None:
            return wm
        return getattr(self.model, "wm", None)

    def _get_action_dim(self) -> int:
        ad = getattr(self.model, "action_dim", None)
        if ad is not None:
            return int(ad)
        wm = self._get_world_model()
        if wm is not None:
            ad = getattr(wm, "action_dim", None)
            if ad is None:
                wm_cfg = getattr(wm, "_wm_config", None)
                if wm_cfg is not None:
                    ad = getattr(wm_cfg, "action_dim", None)
        return int(ad) if ad is not None else 2

    def _reward_head_uses_symlog(self, world_model: nn.Module) -> bool:
        """Detect whether the reward head outputs in symlog space.

        Checks for a ``symlog`` attribute on the reward head, or a
        ``use_symlog`` flag on the world-model config.
        """
        rh = getattr(world_model, "reward_head", None)
        if rh is not None:
            if hasattr(rh, "symlog"):
                return True
            if hasattr(rh, "use_symlog"):
                return bool(rh.use_symlog)
        wm_cfg = getattr(world_model, "_wm_config", None)
        if wm_cfg is not None:
            return bool(getattr(wm_cfg, "reward_symlog", True))
        # Conservative default: assume symlog
        return True

    def _convert_reward_to_real(
        self,
        r_pred: Tensor,
        world_model: Optional[nn.Module],
    ) -> Tensor:
        """Convert a predicted reward from symlog space to real space.

        [BUG-9.2 FIX] The reward head typically outputs in symlog space.
        This method checks and applies symexp if necessary.

        Parameters
        ----------
        r_pred : Tensor
            Raw reward prediction from the world model.
        world_model : nn.Module or None

        Returns
        -------
        Tensor
            Reward in real (linear) scale.
        """
        if world_model is None:
            return r_pred

        if not self._reward_head_uses_symlog(world_model):
            return r_pred

        # Apply symexp to convert from symlog → real
        rh = getattr(world_model, "reward_head", None)
        if rh is not None and hasattr(rh, "symexp"):
            # Use the reward head's own symexp if available
            return rh.symexp(r_pred)

        # Fallback to the global symexp
        return symexp(r_pred, max_val=self.symlog_clip)

    # ── World model step ────────────────────────────────────────────────

    def _step_world_model(
        self,
        world_model: Optional[nn.Module],
        wm_state: Any,
        current: Tensor,
        action: Tensor,
        action_dim: int,
    ) -> Tuple[Any, Tensor, Tensor, Optional[Tensor]]:
        """Advance one imagination step.

        [BUG-9.1 FIX] Returns the **new** wm_state as the first element
        so the caller can rebind its local variable.  The old code tried
        ``wm_state.__dict__.update(wm_state_new.__dict__)`` which does
        NOT update the caller's reference — all subsequent steps would
        use stale hidden state.

        Returns
        -------
        new_wm_state : Any
            Updated world-model hidden state (caller must reassign).
        next_state : Tensor, shape ``(B, D)``
            Predicted next observation.
        reward : Tensor, shape ``(B,)``
            Predicted reward in **real** (linear) scale.
        continue_prob : Tensor or None, shape ``(B,)``
            Probability of the episode continuing, or None if no
            continue head is available.
        """
        B = current.shape[0]

        # ── Primary path: forward_imagination ───────────────────────────
        if (
            world_model is not None
            and wm_state is not None
            and hasattr(world_model, "forward_imagination")
        ):
            # [BUG-9.1 FIX] Capture the new state directly
            wm_state_new, rssm_out = world_model.forward_imagination(
                action, wm_state
            )

            # ── Reward extraction + symlog → real conversion ────────────
            r_pred = getattr(rssm_out, "r_pred", None)
            if r_pred is None and hasattr(world_model, "reward_head"):
                feat = getattr(rssm_out, "features_prior", None)
                if feat is not None:
                    rh = world_model.reward_head
                    if hasattr(rh, "predict_real"):
                        # predict_real already returns real-scale
                        r_pred = rh.predict_real(feat)
                    else:
                        r_pred = rh(feat)

            if r_pred is None:
                r_pred = torch.zeros(B, device=self.device)
            else:
                # [BUG-9.2 FIX] Convert symlog → real
                # Skip conversion if predict_real was used (already real)
                if not (
                    hasattr(world_model, "reward_head")
                    and hasattr(world_model.reward_head, "predict_real")
                    and getattr(rssm_out, "r_pred", None) is None
                ):
                    r_pred = self._convert_reward_to_real(r_pred, world_model)

            if r_pred.dim() > 1:
                r_pred = r_pred.squeeze(-1)

            # ── Next observation ────────────────────────────────────────
            next_state = getattr(rssm_out, "o_pred", current)

            # ── Continue probability ────────────────────────────────────
            cp = getattr(rssm_out, "continue_prob", None)
            if cp is None and hasattr(world_model, "continue_head"):
                feat = getattr(rssm_out, "features_prior", None)
                if feat is not None:
                    # FIX: continue_head() returns logits, get_prob() returns sigmoid
                    cp = world_model.continue_head.get_prob(feat)
            
            if cp is not None and cp.dim() > 1:
                cp = cp.squeeze(-1)
            
            return wm_state_new, next_state, r_pred, cp

        # ── Fallback: linear dynamics placeholder ───────────────────────
        a = action
        if a.shape[-1] < current.shape[-1]:
            a = F.pad(a, (0, current.shape[-1] - a.shape[-1]))
        elif a.shape[-1] > current.shape[-1]:
            a = a[:, : current.shape[-1]]

        return wm_state, current + 0.1 * a, torch.zeros(B, device=self.device), None

    # ── Public API ──────────────────────────────────────────────────────

    @staticmethod
    def _compute_lambda_returns(
        rewards: Tensor,
        values: Tensor,
        continue_probs: Optional[Tensor],
        gamma: float,
        lambda_: float,
    ) -> Tensor:
        B, H = rewards.shape
        if continue_probs is not None:
            disc = gamma * continue_probs
        else:
            disc = torch.full_like(rewards, gamma)

        returns = torch.zeros(B, H, device=rewards.device)
        last = values[:, -1]
        for t in reversed(range(H)):
            last = rewards[:, t] + disc[:, t] * (
                (1.0 - lambda_) * values[:, t + 1] + lambda_ * last
            )
            returns[:, t] = last
        return returns

    def imagine_rollout_differentiable(
        self,
        initial_state: Tensor,
        initial_prev_action: Optional[Tensor],
        horizon: int,
        actor: nn.Module,
        critic: nn.Module,
        initial_wm_state: Optional[Any] = None,
    ) -> Dict[str, Tensor]:
        B = initial_state.shape[0]
        horizon = min(horizon, self.max_horizon)
        world_model = self._get_world_model()
        action_dim = self._get_action_dim()

        if world_model is None:
            raise RuntimeError("imagine_rollout_differentiable requires a world_model.")

        rssm = getattr(world_model, "state_transition", None)
        if rssm is None:
            raise RuntimeError("world_model.state_transition is required for differentiable imagination.")

        wm_cfg = getattr(world_model, "_wm_config", None)
        is_discrete = bool(getattr(wm_cfg, "is_discrete_action", False)) if wm_cfg else False

        if initial_wm_state is not None:
            wm_state = initial_wm_state
            if hasattr(wm_state, "detach_all"):
                wm_state = wm_state.detach_all()
        else:
            with torch.no_grad():
                wm_state = world_model.init_wm_state(B, self.device)
                if initial_prev_action is not None:
                    a_prev = initial_prev_action.to(self.device)
                    if a_prev.dim() == 3:
                        a_prev = a_prev[:, -1]
                    if a_prev.shape[-1] != action_dim:
                        a_prev = a_prev.reshape(B, -1)
                        if a_prev.shape[-1] > action_dim:
                            a_prev = a_prev[:, :action_dim]
                        elif a_prev.shape[-1] < action_dim:
                            a_prev = F.pad(a_prev, (0, action_dim - a_prev.shape[-1]))
                else:
                    a_prev = torch.zeros(B, action_dim, device=self.device)
                    if is_discrete and action_dim > 0:
                        a_prev[:, 0] = 1.0
                wm_state, _ = world_model.forward_context(initial_state, a_prev, wm_state)

        frozen_params = []
        for module in (world_model, critic):
            if isinstance(module, nn.Module):
                for param in module.parameters():
                    frozen_params.append((param, param.requires_grad))
                    param.requires_grad_(False)

        try:
            imag_feats = []
            imag_rssm_feats = []
            imag_actions = []
            imag_log_probs = []
            imag_entropies = []

            for _ in range(horizon):
                if self.model is not None and hasattr(self.model, "policy_from_wm_state"):
                    feat = self.model.policy_from_wm_state(wm_state)
                else:
                    feat = rssm.get_features(wm_state.h_shared, wm_state.z)
                imag_feats.append(feat)

                dist = actor(feat.detach())
                if hasattr(dist, "rsample"):
                    action = dist.rsample()
                else:
                    action = dist.sample()
                action_for_log_prob = action.detach() if isinstance(action, torch.Tensor) and action.requires_grad else action
                log_prob = dist.log_prob(action_for_log_prob)
                if log_prob.dim() > 1:
                    log_prob = log_prob.sum(dim=-1)
                entropy = dist.entropy()
                if entropy.dim() > 1:
                    entropy = entropy.sum(dim=-1)

                imag_actions.append(action)
                imag_log_probs.append(log_prob)
                imag_entropies.append(entropy)

                wm_state, rssm_outputs = world_model.forward_imagination(
                    action_prev=action,
                    prev_state=wm_state,
                )
                if hasattr(rssm_outputs, "features_prior") and rssm_outputs.features_prior is not None:
                    imag_rssm_feats.append(rssm_outputs.features_prior)
                else:
                    imag_rssm_feats.append(
                        rssm.get_features(wm_state.h_shared, wm_state.z)
                    )

            if self.model is not None and hasattr(self.model, "policy_from_wm_state"):
                final_feat = self.model.policy_from_wm_state(wm_state)
            else:
                final_feat = rssm.get_features(wm_state.h_shared, wm_state.z)
            imag_feats.append(final_feat)

            feats = torch.stack(imag_feats, dim=1)
            actions = torch.stack(imag_actions, dim=1)
            log_probs = torch.stack(imag_log_probs, dim=1)
            entropies = torch.stack(imag_entropies, dim=1)

            rssm_feats = torch.stack(imag_rssm_feats, dim=1)
            rewards_raw = world_model.reward_head(rssm_feats)
            rewards = self._convert_reward_to_real(rewards_raw, world_model)
            if rewards.dim() > 2:
                rewards = rewards.squeeze(-1)
            rewards = rewards.clamp(-self.reward_clip, self.reward_clip)

            continue_probs = None
            if hasattr(world_model, "continue_head") and world_model.continue_head is not None:
                if hasattr(world_model.continue_head, "get_prob"):
                    continue_probs = world_model.continue_head.get_prob(rssm_feats)
                else:
                    continue_probs = torch.sigmoid(world_model.continue_head(rssm_feats))
                if continue_probs.dim() > 2:
                    continue_probs = continue_probs.squeeze(-1)

            use_fixed_gamma = bool(getattr(self, "use_fixed_gamma_for_imag", False))
            if use_fixed_gamma:
                continue_probs = None

            values_raw = critic(feats)
            values = extract_real_value(values_raw)
            if values.dim() > 2:
                values = values.squeeze(-1)
        finally:
            for param, requires_grad in frozen_params:
                param.requires_grad_(requires_grad)

        returns = self._compute_lambda_returns(
            rewards=rewards,
            values=values,
            continue_probs=continue_probs,
            gamma=self._gamma_buf,
            lambda_=self.gae_lambda,
        )

        return {
            "policy_features": feats,
            "actions": actions,
            "log_probs": log_probs,
            "entropies": entropies,
            "rewards": rewards,
            "values": values,
            "returns": returns,
            "continue_probs": continue_probs,
        }

    def imagine_rollout(
        self,
        initial_state: Tensor,
        horizon: int,
        policy_fn: Optional[Callable] = None,
    ) -> Dict[str, Tensor]:
        """Imagine a batch of trajectories from *initial_state*.

        Parameters
        ----------
        initial_state : Tensor, shape ``(B, state_dim)``
        horizon : int
            Number of imagination steps (capped at ``max_horizon``).
        policy_fn : callable, optional
            ``policy_fn(state) → action``.  If ``None``, uses
            ``self.model`` to sample actions.

        Returns
        -------
        dict with keys:
            ``states``  : ``(B, H+1, D)``
            ``actions`` : ``(B, H, A)``
            ``rewards`` : ``(B, H)``    — in **real** (linear) scale
            ``values``  : ``(B, H+1)``
            ``dones``   : ``(B, H)``    — 1.0 where continue-head truncated
        """
        B = initial_state.shape[0]
        horizon = min(horizon, self.max_horizon)
        action_dim = self._get_action_dim()
        world_model = self._get_world_model()

        # Pre-allocate output tensors
        states = torch.zeros(
            B, horizon + 1, *initial_state.shape[1:],
            device=self.device, dtype=initial_state.dtype,
        )
        actions_out = torch.zeros(B, horizon, action_dim, device=self.device)
        rewards_out = torch.zeros(B, horizon, device=self.device)
        values_out = torch.zeros(B, horizon + 1, device=self.device)
        dones_out = torch.zeros(B, horizon, device=self.device)
        continue_probs_out = torch.ones(B, horizon, device=self.device)  # [v5.5]

        states[:, 0] = initial_state
        current = initial_state

        # ── Initialise WM hidden state ──────────────────────────────────
        wm_state = None
        if (
            world_model is not None
            and hasattr(world_model, "init_wm_state")
            and hasattr(world_model, "forward_context")
        ):
            wm_cfg = getattr(world_model, "_wm_config", None)
            is_discrete = bool(
                getattr(wm_cfg, "is_discrete_action", False)
            ) if wm_cfg else False
            a_prev = torch.zeros(B, action_dim, device=self.device)
            if is_discrete and action_dim > 0:
                a_prev[:, 0] = 1.0
            wm_state = world_model.init_wm_state(B, self.device)
            wm_state, _ = world_model.forward_context(
                initial_state, a_prev, wm_state
            )

        # Track which trajectories are still alive
        alive = torch.ones(B, device=self.device, dtype=torch.bool)

        for t in range(horizon):
            with torch.no_grad():
                # ── Select action & estimate value ──────────────────────
                if policy_fn is not None:
                    action = policy_fn(current)
                    v_t = torch.zeros(B, device=self.device)
                else:
                    if wm_state is not None and hasattr(self.model, "policy_from_wm_state"):
                        f_policy = self.model.policy_from_wm_state(wm_state)
                        dist = self.model.actor(f_policy)
                        value_raw = self.model.critic(f_policy)
                    else:
                        dist, value_raw = self.model(current)
                    action = dist.sample()
                    v_t = extract_real_value(value_raw)
                    if v_t.dim() > 1:
                        v_t = v_t.squeeze(-1)
                values_out[:, t] = v_t

                # ── Step world model ────────────────────────────────────
                # [BUG-9.1 FIX] Capture new wm_state via return value
                wm_state, next_state, reward_pred, continue_prob = (
                    self._step_world_model(
                        world_model, wm_state, current, action, action_dim
                    )
                )

                # [BUG-2.4] Truncate via continue head
                alive_mask = alive.float()
                if continue_prob is not None:
                    cp = continue_prob.clamp(0.0, 1.0)
                    if self.hard_truncate:
                        alive_prev = alive
                        alive_mask = alive_prev.float()
                        terminated = cp < self.continue_threshold
                        newly_dead = terminated & alive_prev
                        dones_out[:, t] = newly_dead.float()
                        alive = alive_prev & ~terminated
                    else:
                        dones_out[:, t] = (1.0 - cp) * alive.float()
                    continue_probs_out[:, t] = cp  # [v5.5] store raw prob

                # Clamp reward (already in real scale after BUG-9.2 fix)
                reward_pred = reward_pred.clamp(
                    -self.reward_clip, self.reward_clip
                )

                # Only hard-truncation mode masks rewards after done.
                if self.hard_truncate:
                    reward_pred = reward_pred * alive_mask

            actions_out[:, t] = action
            rewards_out[:, t] = reward_pred
            states[:, t + 1] = next_state
            current = next_state

            # Early exit if all trajectories have terminated
            if self.hard_truncate and not alive.any():
                break

        # ── Bootstrap last value ────────────────────────────────────────
        with torch.no_grad():
            if wm_state is not None and hasattr(self.model, "policy_from_wm_state"):
                f_policy = self.model.policy_from_wm_state(wm_state)
                last_val_raw = self.model.critic(
                    f_policy, use_target=True,  # [v5.5] bootstrap with slow EMA target
                )
            else:
                _, last_val_raw = self.model(current)
            last_v = extract_real_value(last_val_raw)
            if last_v.dim() > 1:
                last_v = last_v.squeeze(-1)
            values_out[:, -1] = last_v * alive.float() if self.hard_truncate else last_v

        # ── [v5.5 T4] λ-return (DreamerV3 style) ─────────────────────────
        # G_H = V(s_H)
        # G_t = r_t + discount_t * ((1-λ)*V(s_{t+1}) + λ*G_{t+1})
        lam = getattr(self, "gae_lambda", 0.95)
        returns_out = torch.zeros(B, horizon, device=self.device)
        with torch.no_grad():
            G = values_out[:, -1]  # bootstrap: V(s_H)
            for t in reversed(range(horizon)):
                disc = continue_probs_out[:, t] * getattr(self, "_gamma_buf", 0.99)
                G = rewards_out[:, t] + disc * ((1.0 - lam) * values_out[:, t + 1] + lam * G)
                returns_out[:, t] = G

        return {
            "states": states,
            "actions": actions_out,
            "rewards": rewards_out,
            "values": values_out,
            "dones": dones_out,
            "continue_probs": continue_probs_out,  # [v5.5] soft discount
            "returns": returns_out,  # [v5.5 T4] λ-return
        }

    def compute_imagined_returns(
        self,
        rollout: Dict[str, Tensor],
        gamma: float = 0.99,
    ) -> Tensor:
        """Compute discounted returns from an imagined rollout.

        Parameters
        ----------
        rollout : dict
            Output of :meth:`imagine_rollout`.  Rewards are assumed
            to already be in real (linear) scale.
        gamma : float

        Returns
        -------
        Tensor, shape ``(B, T)``
        """
        rewards = rollout["rewards"]
        values = rollout["values"]
        B, T = rewards.shape

        returns = torch.zeros(B, T, device=self.device)
        next_ret = values[:, -1]
        for t in reversed(range(T)):
            returns[:, t] = rewards[:, t] + gamma * next_ret
            next_ret = returns[:, t]
        return returns


# ══════════════════════════════════════════════════════════════════════════════
#  END OF SECTION 9
# ══════════════════════════════════════════════════════════════════════════════

# ══════════════════════════════════════════════════════════════════════════════
#  SECTION 10 ▸ DATA COLLECTION (RolloutCollector)
# ══════════════════════════════════════════════════════════════════════════════
#
#  Depends on: SECTION 1 (extract_real_value)
#              SECTION 7 (compute_policy_outputs — internally)
#
#  Public API
#  ──────────
#    RolloutCollector  — interact with env, return trajectory data
#
#  Critical fixes
#  ──────────────
#    [BUG-1.4] Terminal next_obs is stored BEFORE env.reset() so the
#              trajectory data contains the correct (s, a, r, s') tuples
#              at episode boundaries.
#    [BUG-1.5] collect() returns explicit next_observations alongside
#              observations, eliminating off-by-one errors in
#              TrainingLoop._add_to_buffer().
#
#  Private helpers
#  ───────────────
#    _ensure_env_wrapper()        — lazy env wrapping
#    _convert_action_for_env()    — tensor → numpy, discrete argmax
# ══════════════════════════════════════════════════════════════════════════════


def _ensure_env_wrapper(env: Any, seed: Optional[int] = None) -> Any:
    """Wrap *env* in EnvWrapper if it isn't one already."""
    if env is None:
        return None
    from .aletheia_api import EnvWrapper
    if isinstance(env, EnvWrapper):
        return env
    return EnvWrapper.from_env(env, seed=seed) if seed is not None else EnvWrapper.from_env(env)


def _convert_action_for_env(action: Tensor, env: Any) -> np.ndarray:
    """Convert a model action tensor to a numpy value the env accepts.

    For discrete action spaces (``env.action_space.n`` exists) the
    action is argmax-ed to a scalar int.
    """
    a = action.detach().cpu().numpy()
    if hasattr(getattr(env, "action_space", None), "n"):
        a = int(a.argmax()) if a.ndim >= 1 else int(a)
    return a


class RolloutCollector:
    """Collect environment trajectories using a given policy.

    Parameters
    ----------
    model : nn.Module
        Actor-critic model (called with ``model(obs)`` → ``(dist, value)``).
    env : gym-like
        Environment with ``reset()`` / ``step()`` API.
    device : torch.device
    max_steps : int
        Maximum steps per episode before forced reset.
    """

    def __init__(
        self,
        model: nn.Module,
        env: Any,
        device: torch.device,
        max_steps: int = 1000,
    ):
        self.model = model
        self.env = _ensure_env_wrapper(env)
        self.device = device
        self.max_steps = max_steps

        self.current_obs: Optional[Tensor] = None
        self.current_step = 0
        self.episode_return = 0.0

        self.episode_returns: List[float] = []
        self.episode_lengths: List[int] = []

    def reset(self) -> Tensor:
        """Reset environment, return initial observation as a ``(1, D)`` tensor."""
        obs = self.env.reset()
        self.current_obs = torch.from_numpy(np.asarray(obs, dtype=np.float32)).unsqueeze(0).to(self.device)
        self.current_step = 0
        self.episode_return = 0.0
        return self.current_obs

    # ────────────────────────────────────────────────────────────────────

    def _collect_impl(
        self,
        num_steps: int,
        deterministic: bool = False,
    ) -> Dict[str, np.ndarray]:
        """Core collection loop.

        Returns a dict with **both** ``observations`` (s_t) and
        ``next_observations`` (s_{t+1}) so downstream code never has to
        guess alignment.
        """
        observations: List[np.ndarray] = []
        next_observations: List[np.ndarray] = []
        actions: List[np.ndarray] = []
        rewards_list: List[float] = []
        dones_list: List[float] = []
        terminated_list: List[float] = []
        truncated_list: List[float] = []
        values_list: List[float] = []
        log_probs_list: List[float] = []

        if self.current_obs is None:
            self.reset()

        for _ in range(num_steps):
            with torch.no_grad():
                dist, value_raw = self.model(self.current_obs)
                if deterministic:
                    action = dist.mode if hasattr(dist, "mode") else dist.mean
                else:
                    action = dist.sample()

                lp = dist.log_prob(action)
                if lp.dim() > 1:
                    lp = lp.sum(dim=-1)

            # ── Record CURRENT obs ──────────────────────────────────────
            obs_np = self.current_obs.cpu().numpy()[0]
            observations.append(obs_np)

            # ── Step environment ────────────────────────────────────────
            action_env = _convert_action_for_env(action[0], self.env)
            next_obs_np, reward, terminated, truncated, info = self.env.step(action_env)
            next_obs_np = np.asarray(next_obs_np, dtype=np.float32)
            next_step = self.current_step + 1
            forced_truncate = bool(next_step >= self.max_steps)
            terminated_step = bool(terminated)
            truncated_step = bool(truncated) or forced_truncate
            done = terminated_step or truncated_step

            # [BUG-1.4 FIX] Store next_obs BEFORE potential reset
            next_observations.append(next_obs_np)
            actions.append(action.cpu().numpy()[0])
            rewards_list.append(float(reward))
            dones_list.append(float(done))
            terminated_list.append(float(terminated_step))
            truncated_list.append(float(truncated_step))

            v = extract_real_value(value_raw)
            values_list.append(float(v.cpu().numpy().ravel()[0]))
            log_probs_list.append(float(lp.cpu().numpy().ravel()[0]))

            self.episode_return += reward
            self.current_step = next_step

            if done or self.current_step >= self.max_steps:
                self.episode_returns.append(self.episode_return)
                self.episode_lengths.append(self.current_step)
                self.reset()
            else:
                self.current_obs = (
                    torch.from_numpy(next_obs_np).unsqueeze(0).to(self.device)
                )

        return {
            "observations": np.array(observations),
            "next_observations": np.array(next_observations),
            "actions": np.array(actions),
            "rewards": np.array(rewards_list, dtype=np.float32),
            "dones": np.array(dones_list, dtype=np.float32),
            "terminated": np.array(terminated_list, dtype=np.float32),
            "truncated": np.array(truncated_list, dtype=np.float32),
            "values": np.array(values_list, dtype=np.float32),
            "log_probs": np.array(log_probs_list, dtype=np.float32),
        }

    # ────────────────────────────────────────────────────────────────────

    def collect(
        self,
        num_steps: int,
        deterministic: bool = False,
    ) -> Dict[str, np.ndarray]:
        """Collect *num_steps* transitions.

        The model is switched to eval mode during collection and
        restored to train mode afterwards.
        """
        was_training = bool(self.model.training)
        self.model.eval()
        try:
            return self._collect_impl(num_steps, deterministic)
        except Exception as e:
            logger.exception(f"Error during data collection: {e}")
            raise
        finally:
            self.model.train(was_training)

    def get_statistics(self) -> Dict[str, float]:
        """Return aggregate episode statistics."""
        if not self.episode_returns:
            return {"mean_return": 0.0, "mean_length": 0.0, "num_episodes": 0}
        return {
            "mean_return": float(np.mean(self.episode_returns)),
            "std_return": float(np.std(self.episode_returns)),
            "mean_length": float(np.mean(self.episode_lengths)),
            "num_episodes": len(self.episode_returns),
            "min_return": float(np.min(self.episode_returns)),
            "max_return": float(np.max(self.episode_returns)),
        }

    def reset_statistics(self):
        self.episode_returns.clear()
        self.episode_lengths.clear()


