        target_critic_raw_mean = float(target_critic_raw.mean().item())
        target_critic_delta_mean = 0.0
        behavior_action_switch_rate = 0.0
        behavior_action_switch_rate_preinflation = 0.0
        behavior_action_oscillation_rate = 0.0
        behavior_action_oscillation_rate_preinflation = 0.0
        behavior_corridor_persistence_rate = 0.0
        behavior_corridor_entry_rate = 0.0
        behavior_corridor_exit_rate = 0.0
