        behavior_f_policy_velocity_corridor_mean = 0.0
        behavior_f_policy_velocity_preinflation_mean = 0.0
        behavior_f_policy_acceleration_mean = 0.0
        behavior_f_policy_acceleration_preinflation_mean = 0.0
        behavior_f_policy_curvature_preinflation_mean = 0.0
        if behavior_policy_features is not None and behavior_policy_features.shape[1] > 1:
            delta_feat = behavior_policy_features[:, 1:] - behavior_policy_features[:, :-1]
            velocity = torch.linalg.vector_norm(delta_feat.detach(), dim=-1)
            corridor_pair_mask = (
                corridor_semantic_corridor_mask[:, 1:]
                * corridor_semantic_corridor_mask[:, :-1]
            ).detach()
            preinflation_pair_mask = (
                behavior_preinflation_mask[:, 1:]
                * behavior_preinflation_mask[:, :-1]
            ).detach()
            behavior_f_policy_velocity_mean = float(velocity.mean().item())
            behavior_f_policy_velocity_corridor_mean = float(
                _masked_mean_tensor(velocity, corridor_pair_mask).item()
            )
            behavior_f_policy_velocity_preinflation_mean = float(
                _masked_mean_tensor(velocity, preinflation_pair_mask).item()
            )

            if behavior_policy_features.shape[1] > 2:
                second_delta = (
                    behavior_policy_features[:, 2:]
                    - 2.0 * behavior_policy_features[:, 1:-1]
                    + behavior_policy_features[:, :-2]
                )
                acceleration = torch.linalg.vector_norm(
                    second_delta.detach(),
                    dim=-1,
                )
                preinflation_triplet_mask = (
                    behavior_preinflation_mask[:, 2:]
                    * behavior_preinflation_mask[:, 1:-1]
                    * behavior_preinflation_mask[:, :-2]
                ).detach()
                behavior_f_policy_acceleration_mean = float(
                    acceleration.mean().item()
                )
                behavior_f_policy_acceleration_preinflation_mean = float(
                    _masked_mean_tensor(
                        acceleration,
                        preinflation_triplet_mask,
                    ).item()
                )
                curvature = acceleration / (
                    velocity[:, 1:] + velocity[:, :-1] + 1e-6
                )
                behavior_f_policy_curvature_preinflation_mean = float(
                    _masked_mean_tensor(
                        curvature,
                        preinflation_triplet_mask,
                    ).item()
                )

        if (
            behavior_policy_features is not None
            and behavior_policy_features.dim() == 3
            and behavior_policy_features.shape[:2] == corridor_semantic_corridor_mask.shape
        ):
            anchor_actor = getattr(self, "_behavior_policy_eval_anchor_actor", None)
            current_actor = getattr(self.model, "actor", None) if self.model is not None else None
            if anchor_actor is not None and callable(anchor_actor) and current_actor is not None and callable(current_actor):
                try:
                    with torch.no_grad():
                        feats_flat = behavior_policy_features.detach().reshape(
                            -1, behavior_policy_features.shape[-1]
                        )
                        current_dist = current_actor(feats_flat)
                        anchor_dist = anchor_actor(feats_flat)
                        kl_flat = _compute_distribution_kl_tensor(
                            anchor_dist,
                            current_dist,
                        )
                    if isinstance(kl_flat, Tensor) and kl_flat.numel() == corridor_semantic_corridor_mask.numel():
                        kl_tensor = kl_flat.reshape_as(corridor_semantic_corridor_mask).detach()
                        behavior_policy_eval_anchor_available = 1.0
                        anchor_step = int(getattr(self, "_behavior_policy_eval_anchor_step", -1))
                        behavior_policy_eval_anchor_age_steps = float(
                            max(0, int(getattr(self, "global_step", 0)) - anchor_step)
                        )
                        behavior_policy_kl_to_eval_anchor_mean = float(
                            kl_tensor.mean().item()
                        )
                        behavior_policy_kl_to_eval_anchor_corridor_mean = float(
                            _masked_mean_tensor(
                                kl_tensor,
                                corridor_semantic_corridor_mask,
                            ).item()
                        )
                        behavior_policy_kl_to_eval_anchor_preinflation_mean = float(
                            _masked_mean_tensor(
                                kl_tensor,
                                behavior_preinflation_mask,
                            ).item()
                        )
                except Exception:
                    pass

            if current_actor is not None and callable(current_actor):
                feats_flat = behavior_policy_features.detach().reshape(
                    -1, behavior_policy_features.shape[-1]
                )
                registry_kl_flat, registry_size = _compute_policy_bank_min_kl_tensor(
                    current_actor,
                    getattr(
                        self,
                        "_real_stability_certified_anchor_registry_actors",
                        [],
                    ),
                    feats_flat,
                )
                if (
                    isinstance(registry_kl_flat, Tensor)
                    and registry_kl_flat.numel()
                    == corridor_semantic_corridor_mask.numel()
                ):
                    registry_kl_tensor = registry_kl_flat.reshape_as(
                        corridor_semantic_corridor_mask
                    ).detach()
                    registry_support_mask = (
                        registry_kl_tensor <= _REAL_STABILITY_CORRIDOR_KL_THRESHOLD
                    ).to(dtype=advantages.dtype)
                    behavior_policy_geometry_registry_support_mask = (
                        registry_support_mask.detach()
                    )
                    behavior_policy_certified_registry_available = 1.0
                    behavior_policy_certified_registry_size = float(registry_size)
                    behavior_policy_kl_to_certified_registry_mean = float(
                        registry_kl_tensor.mean().item()
                    )
                    behavior_policy_kl_to_certified_registry_corridor_mean = float(
                        _masked_mean_tensor(
                            registry_kl_tensor,
                            corridor_semantic_corridor_mask,
                        ).item()
                    )
                    behavior_policy_kl_to_certified_registry_preinflation_mean = float(
                        _masked_mean_tensor(
                            registry_kl_tensor,
                            behavior_preinflation_mask,
                        ).item()
                    )
                    behavior_policy_geometry_registry_support_fraction = float(
                        registry_support_mask.mean().item()
                    )
                    behavior_policy_geometry_registry_corridor_support_fraction = float(
                        _masked_mean_tensor(
                            registry_support_mask,
                            corridor_semantic_corridor_mask,
                        ).item()
                    )
                    behavior_policy_geometry_registry_preinflation_support_fraction = float(
                        _masked_mean_tensor(
                            registry_support_mask,
                            behavior_preinflation_mask,
                        ).item()
                    )
        if behavior_policy_certified_registry_available > 0.0:
            reward_semantic_registry_gate_scalar = min(
                1.0,
                max(0.0, real_task_cert_gate),
            )
            behavior_policy_reward_semantic_registry_gate = torch.full_like(
                advantages,
                reward_semantic_registry_gate_scalar,
            )
            behavior_policy_reward_semantic_registry_support_mask = (
                behavior_policy_geometry_registry_support_mask.detach()
                * behavior_policy_reward_semantic_registry_gate.detach()
            ).clamp(0.0, 1.0)
            behavior_policy_certified_registry_support_mask = (
                torch.minimum(
                    behavior_policy_geometry_registry_support_mask.detach(),
                    behavior_policy_task_cert_support_mask.detach(),
                ).clamp(0.0, 1.0)
            )
            behavior_policy_reward_semantic_registry_gate_mean = float(
                reward_semantic_registry_gate_scalar
            )
            behavior_policy_reward_semantic_registry_support_fraction = float(
                behavior_policy_reward_semantic_registry_support_mask.mean().item()
            )
            behavior_policy_reward_semantic_registry_corridor_support_fraction = float(
                _masked_mean_tensor(
                    behavior_policy_reward_semantic_registry_support_mask,
                    corridor_semantic_corridor_mask,
                ).item()
            )
            behavior_policy_reward_semantic_registry_preinflation_support_fraction = float(
                _masked_mean_tensor(
                    behavior_policy_reward_semantic_registry_support_mask,
                    behavior_preinflation_mask,
                ).item()
            )
            behavior_policy_certified_registry_support_fraction = float(
                behavior_policy_certified_registry_support_mask.mean().item()
            )
            behavior_policy_certified_registry_corridor_support_fraction = float(
                _masked_mean_tensor(
                    behavior_policy_certified_registry_support_mask,
                    corridor_semantic_corridor_mask,
                ).item()
            )
            behavior_policy_certified_registry_preinflation_support_fraction = float(
                _masked_mean_tensor(
                    behavior_policy_certified_registry_support_mask,
                    behavior_preinflation_mask,
                ).item()
            )
            actor_contract_certified_registry_support_mean = float(
                _masked_mean_tensor(
                    behavior_policy_certified_registry_support_mask,
                    corridor_semantic_corridor_mask,
                ).item()
            )
            actor_contract_certified_registry_mismatch_mean = float(
                _masked_mean_tensor(
                    1.0 - behavior_policy_certified_registry_support_mask,
                    corridor_semantic_corridor_mask,
                ).item()
            )

        if actions_im is not None and actions_im.dim() == 3 and actions_im.shape[1] > 1:
            action_indices = None
            if actions_im.shape[-1] > 1:
                action_indices = actions_im.detach().argmax(dim=-1)
            if action_indices is not None:
                switch_indicator = (
                    action_indices[:, 1:] != action_indices[:, :-1]
                ).to(dtype=advantages.dtype)
                preinflation_pair_mask = (
                    behavior_preinflation_mask[:, 1:]
                    * behavior_preinflation_mask[:, :-1]
                ).detach()
                behavior_action_switch_rate = float(
                    switch_indicator.mean().item()
                )
                behavior_action_switch_rate_preinflation = float(
                    _masked_mean_tensor(
                        switch_indicator,
                        preinflation_pair_mask,
                    ).item()
                )
                if action_indices.shape[1] > 2:
                    oscillation_indicator = (
                        (action_indices[:, 2:] == action_indices[:, :-2])
                        & (action_indices[:, 2:] != action_indices[:, 1:-1])
                    ).to(dtype=advantages.dtype)
                    preinflation_triplet_mask = (
                        behavior_preinflation_mask[:, 2:]
                        * behavior_preinflation_mask[:, 1:-1]
                        * behavior_preinflation_mask[:, :-2]
                    ).detach()
                    behavior_action_oscillation_rate = float(
                        oscillation_indicator.mean().item()
                    )
                    behavior_action_oscillation_rate_preinflation = float(
                        _masked_mean_tensor(
                            oscillation_indicator,
                            preinflation_triplet_mask,
                        ).item()
                    )

        if corridor_semantic_corridor_mask.dim() == 2 and corridor_semantic_corridor_mask.shape[1] > 1:
            corridor_prev = corridor_semantic_corridor_mask[:, :-1]
            corridor_next = corridor_semantic_corridor_mask[:, 1:]
            corridor_prev_sum = float(corridor_prev.sum().item())
            corridor_non_prev_sum = float((1.0 - corridor_prev).sum().item())
            if corridor_prev_sum > 0.0:
                behavior_corridor_persistence_rate = float(
                    (corridor_prev * corridor_next).sum().item() / corridor_prev_sum
                )
                behavior_corridor_exit_rate = float(
                    (corridor_prev * (1.0 - corridor_next)).sum().item()
                    / corridor_prev_sum
                )
            if corridor_non_prev_sum > 0.0:
                behavior_corridor_entry_rate = float(
                    (((1.0 - corridor_prev) * corridor_next).sum().item())
                    / corridor_non_prev_sum
                )

        real_stability_telemetry = bootstrap_external_eval_feedback_telemetry
        real_behavior_available = float(resolved_external_feedback_available)
        real_behavior_step = int(bootstrap_external_eval_feedback_last_step)
        real_behavior_age_steps = float(resolved_external_feedback_age_steps)
        real_behavior_action_entropy_mean = float(
            real_stability_telemetry.get("real_behavior_action_entropy_mean", 0.0)
        )
        real_behavior_action_switch_rate = float(
            resolved_real_behavior_action_switch_rate
        )
        real_behavior_action_oscillation_rate = float(
            resolved_real_behavior_action_oscillation_rate
        )
        real_reward_health = float(
            real_stability_telemetry.get(
                "real_reward_health",
                _compute_reward_health(
                    float(
                        getattr(
                            self,
                            "_bootstrap_external_eval_feedback_last_mean",
                            getattr(self, "_external_eval_last_mean", -float("inf")),
                        )
                    ),
                    float(
                        getattr(
                            self,
                            "_bootstrap_external_eval_feedback_best_mean",
                            getattr(self, "_external_eval_best_mean", -float("inf")),
                        )
                    ),
                ),
            )
        )
        real_reward_degradation = float(resolved_real_reward_degradation)
        real_corridor_occupancy_fraction = float(
            real_stability_telemetry.get("real_corridor_occupancy_fraction", 0.0)
        )
        real_corridor_persistence_rate = float(
            real_stability_telemetry.get("real_corridor_persistence_rate", 0.0)
        )
        real_corridor_entry_rate = float(
            real_stability_telemetry.get("real_corridor_entry_rate", 0.0)
        )
        real_corridor_exit_rate = float(
            real_stability_telemetry.get("real_corridor_exit_rate", 0.0)
        )
        real_policy_certified_anchor_available = float(
            real_stability_telemetry.get("real_policy_certified_anchor_available", 0.0)
        )
        real_policy_certified_anchor_step = int(
            getattr(self, "_real_stability_certified_anchor_step", -1)
        )
        real_policy_certified_anchor_age_steps = (
            float(
                max(
                    0,
                    int(getattr(self, "global_step", 0))
                    - real_policy_certified_anchor_step,
                )
            )
            if real_policy_certified_anchor_step >= 0
            else -1.0
        )
        real_policy_kl_to_certified_anchor_mean = float(
            real_stability_telemetry.get(
                "real_policy_kl_to_certified_anchor_mean",
                0.0,
            )
        )
        real_policy_certified_registry_available = float(
            real_stability_telemetry.get("real_policy_certified_registry_available", 0.0)
        )
        real_policy_certified_registry_size = float(
            real_stability_telemetry.get("real_policy_certified_registry_size", 0.0)
        )
        real_policy_kl_to_certified_registry_mean = float(
            real_stability_telemetry.get(
                "real_policy_kl_to_certified_registry_mean",
                0.0,
            )
        )
        real_imag_corridor_occupancy_gap = 0.0
        real_imag_corridor_persistence_gap = 0.0
        real_imag_policy_anchor_drift_gap = 0.0
        real_imag_policy_registry_drift_gap = 0.0
        real_imag_stability_disagreement = 0.0
        if real_policy_certified_anchor_available > 0.0:
            real_imag_corridor_occupancy_gap = float(
                behavior_corridor_occupancy_fraction
                - real_corridor_occupancy_fraction
            )
            real_imag_corridor_persistence_gap = float(
                behavior_corridor_persistence_rate
                - real_corridor_persistence_rate
            )
            real_imag_policy_anchor_drift_gap = float(
                real_policy_kl_to_certified_anchor_mean
                - behavior_policy_kl_to_eval_anchor_mean
            )
            imag_stability_score = 0.5 * (
                behavior_corridor_occupancy_fraction
                + behavior_corridor_persistence_rate
            )
            real_stability_score = 0.5 * (
                real_corridor_occupancy_fraction
                + real_corridor_persistence_rate
            )
            real_imag_stability_disagreement = float(
                max(0.0, imag_stability_score - real_stability_score)
            )
        if (
            real_policy_certified_registry_available > 0.0
            and behavior_policy_certified_registry_available > 0.0
        ):
            real_imag_policy_registry_drift_gap = float(
                real_policy_kl_to_certified_registry_mean
                - behavior_policy_kl_to_certified_registry_mean
            )
        actor_contract_task_mismatch = (
            corridor_semantic_corridor_mask
            * (1.0 - task_corridor_gate.detach())
            * task_corridor_confidence.detach()
        ).clamp(0.0, 1.0)
        if behavior_policy_certified_registry_available > 0.0:
            policy_certified_registry_support = (
                behavior_policy_certified_registry_support_mask.detach()
            )
        else:
            policy_certified_registry_support = torch.ones_like(
                actor_contract_task_mismatch
            )
        actor_contract_registry_mismatch = (
            corridor_semantic_corridor_mask
            * (1.0 - policy_certified_registry_support)
        ).clamp(0.0, 1.0)
        actor_contract_task_mismatch_mean = float(
            _masked_mean_tensor(
                actor_contract_task_mismatch,
                corridor_semantic_corridor_mask,
            ).item()
        )
        actor_contract_certified_registry_support_mean = float(
            _masked_mean_tensor(
                policy_certified_registry_support,
                corridor_semantic_corridor_mask,
            ).item()
        )
        actor_contract_certified_registry_mismatch_mean = float(
            _masked_mean_tensor(
                actor_contract_registry_mismatch,
                corridor_semantic_corridor_mask,
            ).item()
        )
        actor_contract_semantic_certified_mismatch = (
            1.0
            - (1.0 - actor_contract_task_mismatch)
            * (1.0 - actor_contract_registry_mismatch)
        ).clamp(0.0, 1.0)
        actor_contract_semantic_certified_support = (
            1.0 - actor_contract_semantic_certified_mismatch
        ).clamp(0.0, 1.0)
        actor_contract_semantic_certified_support_mean = float(
            _masked_mean_tensor(
                actor_contract_semantic_certified_support,
                corridor_semantic_corridor_mask,
            ).item()
        )
        actor_contract_semantic_certified_mismatch_mean = float(
            _masked_mean_tensor(
                actor_contract_semantic_certified_mismatch,
                corridor_semantic_corridor_mask,
            ).item()
        )
        actor_contract_inflation_pressure = (
            corridor_semantic_corridor_mask
            * corridor_semantic_inflation_gate.detach()
            * corridor_semantic_clean_target_confidence.detach()
        ).clamp(0.0, 1.0)
        actor_contract_inflation_pressure_mean = float(
            _masked_mean_tensor(
                actor_contract_inflation_pressure,
                corridor_semantic_corridor_mask,
            ).item()
        )
        actor_contract_semantic_pressure = torch.maximum(
            actor_contract_semantic_certified_mismatch,
            actor_contract_inflation_pressure,
        ).detach()
        actor_contract_semantic_pressure_mean = float(
            _masked_mean_tensor(
                actor_contract_semantic_pressure,
                corridor_semantic_corridor_mask,
            ).item()
        )
        actor_contract_semantic_trust = (
            1.0
            - corridor_semantic_corridor_mask
            * actor_contract_semantic_pressure
        ).clamp(min=actor_contract_trust_floor, max=1.0).detach()
        actor_contract_semantic_trust_mean = float(
            actor_contract_semantic_trust.mean().item()
        )
        actor_contract_local_semantic_trust = actor_contract_semantic_trust.detach()
        actor_contract_local_semantic_trust_mean = float(
            actor_contract_local_semantic_trust.mean().item()
        )
        actor_contract_unified_trust = actor_contract_local_semantic_trust
        actor_contract_unified_trust_mean = actor_contract_local_semantic_trust_mean
        corridor_semantic_blend_beta = (
            1.0 - actor_contract_semantic_trust
        ).clamp(0.0, 1.0).detach()
        if (
            critic_contract_bootstrap_enabled > 0.0
            and corridor_semantic_clean_target is not None
            and corridor_semantic_clean_target.shape == returns.shape
        ):
            external_eval_last_mean = float(
                getattr(self, "_external_eval_last_mean", -float("inf"))
            )

            critic_anchor_confidence = torch.minimum(
                corridor_semantic_clean_target_confidence.detach(),
                corridor_semantic_clean_target_valid.detach(),
            ).clamp(0.0, 1.0)
            critic_anchor_available = corridor_semantic_clean_target_valid.detach().clamp(
                0.0, 1.0
            )
            critic_contract_anchor_confidence_mean = float(
                critic_anchor_confidence.mean().item()
            )
            critic_contract_task_mismatch_tensor = (
                corridor_semantic_corridor_mask
                * (1.0 - task_corridor_gate.detach())
                * task_corridor_confidence.detach()
            ).clamp(0.0, 1.0)
            if behavior_policy_certified_registry_available > 0.0:
                critic_contract_registry_support = (
                    behavior_policy_certified_registry_support_mask.detach()
                )
            else:
                critic_contract_registry_support = torch.ones_like(
                    critic_contract_task_mismatch_tensor
                )
            critic_contract_registry_mismatch_tensor = (
                corridor_semantic_corridor_mask
                * (1.0 - critic_contract_registry_support)
            ).clamp(0.0, 1.0)
            critic_contract_semantic_certified_mismatch = (
                1.0
                - (1.0 - critic_contract_task_mismatch_tensor)
                * (1.0 - critic_contract_registry_mismatch_tensor)
            ).clamp(0.0, 1.0)
            critic_contract_inflation_pressure = (
                corridor_semantic_corridor_mask
                * corridor_semantic_inflation_gate.detach()
                * critic_anchor_confidence
            ).clamp(0.0, 1.0)
            critic_contract_semantic_pressure = torch.maximum(
                critic_contract_semantic_certified_mismatch,
                critic_contract_inflation_pressure,
            ).detach()
            if critic_contract_bootstrap_enabled > 0.0:
                bootstrap_min_step = max(
                    0,
                    int(
                        getattr(
                            self.config,
                            "adaptive_imag_critic_bootstrap_min_step",
                            1000,
                        )
                    ),
                )
                bootstrap_step_ramp = max(
                    0,
                    int(
                        getattr(
                            self.config,
                            "adaptive_imag_critic_bootstrap_step_ramp",
                            250,
                        )
                    ),
                )
                bootstrap_eval_threshold = max(
                    0.0,
                    float(
                        getattr(
                            self.config,
                            "adaptive_imag_critic_bootstrap_eval_threshold",
                            200.0,
                        )
                    ),
                )
                bootstrap_eval_ramp = max(
                    0.0,
                    float(
                        getattr(
                            self.config,
                            "adaptive_imag_critic_bootstrap_eval_ramp",
                            50.0,
                        )
                    ),
                )
                if bootstrap_step_ramp <= 0:
                    bootstrap_step_gate = (
                        1.0 if self.global_step >= bootstrap_min_step else 0.0
                    )
                else:
                    bootstrap_step_gate = min(
                        1.0,
                        max(
                            0.0,
                            (float(self.global_step) - float(bootstrap_min_step))
                            / float(bootstrap_step_ramp),
                        ),
                    )
                if bootstrap_eval_threshold <= 0.0:
                    bootstrap_eval_gate = 1.0
                elif math.isfinite(external_eval_best_mean):
                    if bootstrap_eval_ramp <= 0.0:
                        bootstrap_eval_gate = (
                            1.0
                            if external_eval_best_mean >= bootstrap_eval_threshold
                            else 0.0
                        )
                    else:
                        bootstrap_eval_gate = min(
                            1.0,
                            max(
                                0.0,
                                (external_eval_best_mean - bootstrap_eval_threshold)
                                / bootstrap_eval_ramp,
                            ),
                        )
                else:
                    bootstrap_eval_gate = 0.0
                critic_contract_bootstrap_eval_gate = float(
                    min(1.0, max(0.0, bootstrap_eval_gate))
                )
                if bootstrap_step_ramp <= 0:
                    bootstrap_precontact_step_gate = bootstrap_step_gate
                else:
                    bootstrap_precontact_start = max(
                        0,
                        bootstrap_min_step - bootstrap_step_ramp,
                    )
                    bootstrap_precontact_step_gate = min(
                        1.0,
                        max(
                            0.0,
                            (
                                float(self.global_step)
                                - float(bootstrap_precontact_start)
                            )
                            / float(bootstrap_step_ramp),
                        ),
                    )
                bootstrap_clean_mix_max = min(
                    1.0,
                    max(
                        0.0,
                        float(
                            getattr(
                                self.config,
                                "adaptive_imag_critic_bootstrap_clean_mix_max",
                                0.8,
                            )
                        ),
                    ),
                )
                bootstrap_external_takeover_floor_ratio = min(
                    1.0,
                    max(
                        0.0,
                        float(
                            getattr(
                                self.config,
                                "adaptive_imag_critic_bootstrap_external_takeover_floor_ratio",
                                1.0,
                            )
                        ),
                    ),
                )
                bootstrap_precontact_floor_max = min(
                    1.0,
                    max(
                        0.0,
                        float(
                            getattr(
                                self.config,
                                "adaptive_imag_critic_bootstrap_precontact_floor_max",
                                0.25,
                            )
                        ),
                    ),
                )
                bootstrap_precontact_frontload = min(
                    1.0,
                    max(
                        0.0,
                        float(
                            getattr(
                                self.config,
                                "adaptive_imag_critic_bootstrap_precontact_frontload",
                                0.0,
                            )
                        ),
                    ),
                )
                bootstrap_semantic_debt_decay = min(
                    1.0,
                    max(
                        0.0,
                        float(
                            getattr(
                                self.config,
                                "adaptive_imag_critic_bootstrap_semantic_debt_decay",
                                0.9,
                            )
                        ),
                    ),
                )
                bootstrap_contact_persistence_decay = min(
                    1.0,
                    max(
                        0.0,
                        float(
                            getattr(
                                self.config,
                                "adaptive_imag_critic_bootstrap_contact_persistence_decay",
                                0.95,
                            )
                        ),
                    ),
                )
                bootstrap_contact_persistence_floor = min(
                    1.0,
                    max(
                        0.0,
                        float(
                            getattr(
                                self.config,
                                "adaptive_imag_critic_bootstrap_contact_persistence_floor",
                                0.35,
                            )
                        ),
                    ),
                )
                bootstrap_anchor_confidence_floor = min(
                    1.0,
                    max(
                        0.0,
                        float(
                            getattr(
                                self.config,
                                "adaptive_imag_critic_bootstrap_anchor_confidence_floor",
                                0.0,
                            )
                        ),
                    ),
                )
                bootstrap_anchor_contact_priority_bonus = max(
                    0.0,
                    float(
                        getattr(
                            self.config,
                            "adaptive_imag_critic_bootstrap_anchor_contact_priority_bonus",
                            2.0,
                        )
                    ),
                )
                bootstrap_dense_contact_priority_floor = min(
                    1.0,
                    max(
                        0.0,
                        float(
                            getattr(
                                self.config,
                                "adaptive_imag_critic_bootstrap_dense_contact_priority_floor",
                                0.35,
                            )
                        ),
                    ),
                )
                bootstrap_anchor_contact_cap = min(
                    1.0,
                    max(
                        bootstrap_clean_mix_max,
                        float(
                            getattr(
                                self.config,
                                "adaptive_imag_critic_bootstrap_anchor_contact_cap",
                                1.0,
                            )
                        ),
                    ),
                )
                raw_bootstrap_values_next = values_im[:, 1:].detach()
                raw_anchor_bootstrap_values_next = torch.cat(
                    (
                        corridor_semantic_clean_target[:, 1:].detach(),
                        values_im[:, -1:].detach(),
                    ),
                    dim=1,
                )
                critic_anchor_available_next = torch.cat(
                    (
                        critic_anchor_available[:, 1:],
                        torch.zeros_like(critic_anchor_available[:, :1]),
                    ),
                    dim=1,
                ).detach()
                critic_anchor_confidence_next = torch.cat(
                    (
                        critic_anchor_confidence[:, 1:],
                        torch.zeros_like(critic_anchor_confidence[:, :1]),
                    ),
                    dim=1,
                ).detach()
                bootstrap_seed_assembly = (
                    _compute_bootstrap_external_seed_assembly_contract(
                        raw_anchor_bootstrap_values_next=raw_anchor_bootstrap_values_next.detach(),
                        raw_bootstrap_values_next=raw_bootstrap_values_next.detach(),
                        critic_anchor_available_next=critic_anchor_available_next.detach(),
                        critic_anchor_confidence_next=critic_anchor_confidence_next.detach(),
                    )
                )
                bootstrap_internal_value_view = raw_bootstrap_values_next.detach()
                bootstrap_external_coverage_view = (
                    bootstrap_seed_assembly.external_coverage_view
                )
                bootstrap_external_confidence_view = (
                    bootstrap_seed_assembly.external_confidence_view
                )
                bootstrap_anchor_valid_mask = (
                    bootstrap_seed_assembly.anchor_valid_mask
                )
                critic_contract_bootstrap_anchor_valid_mask = (
                    bootstrap_anchor_valid_mask
                )
                dense_surface_gain = bootstrap_seed_assembly.dense_surface_gain
                dense_seed_support = bootstrap_seed_assembly.dense_seed_support
                dense_anchor_bootstrap_values_next = (
                    bootstrap_seed_assembly.dense_anchor_bootstrap_values_next
                )
                anchor_bootstrap_values_next = (
                    bootstrap_seed_assembly.anchor_bootstrap_values_next
                )
                bootstrap_external_value_view = anchor_bootstrap_values_next.detach()
                critic_contract_bootstrap_raw_vs_clean_gap = (
                    bootstrap_seed_assembly.raw_vs_clean_gap
                )
                critic_contract_bootstrap_raw_vs_clean_gap_mean = float(
                    _masked_mean_tensor(
                        critic_contract_bootstrap_raw_vs_clean_gap,
                        corridor_semantic_corridor_mask,
                    ).item()
                )
                (
                    critic_contract_bootstrap_eval_drawdown,
                    critic_contract_bootstrap_kinematic_degradation,
                    critic_contract_bootstrap_real_reward_degradation,
                    critic_contract_bootstrap_real_task_degradation,
                    critic_contract_task_degradation,
                    critic_contract_bootstrap_release_guard,
                    critic_contract_bootstrap_negative_adv_pressure,
                    critic_contract_bootstrap_trigger_surface,
                    critic_contract_bootstrap_regime_quality_gate,
                    critic_contract_bootstrap_trigger_gate,
                    critic_contract_bootstrap_late_gate,
                    critic_contract_bootstrap_precontact_gate,
                ) = _compute_bootstrap_trigger_entry_contract(
                    external_eval_best_mean=external_eval_best_mean,
                    external_eval_last_mean=external_eval_last_mean,
                    real_reward_degradation=real_reward_degradation,
                    real_task_cert_gate=real_task_cert_gate,
                    real_behavior_action_switch_rate=real_behavior_action_switch_rate,
                    real_behavior_action_oscillation_rate=real_behavior_action_oscillation_rate,
                    behavior_action_switch_rate_preinflation=behavior_action_switch_rate_preinflation,
                    behavior_action_oscillation_rate_preinflation=behavior_action_oscillation_rate_preinflation,
                    critic_contract_bootstrap_eval_gate=critic_contract_bootstrap_eval_gate,
                    bootstrap_step_gate=bootstrap_step_gate,
                    bootstrap_precontact_step_gate=bootstrap_precontact_step_gate,
                    critic_contract_semantic_pressure=critic_contract_semantic_pressure,
                    critic_anchor_confidence=critic_anchor_confidence,
                    critic_contract_bootstrap_raw_vs_clean_gap=critic_contract_bootstrap_raw_vs_clean_gap,
                    anchor_bootstrap_values_next=anchor_bootstrap_values_next,
                    online_advantages=online_advantages.detach(),
                    returns=returns.detach(),
                    corridor_semantic_corridor_mask=corridor_semantic_corridor_mask,
                )
                critic_contract_bootstrap_trigger_entry_degradation = float(
                    critic_contract_task_degradation
                )
                critic_contract_bootstrap_release_guard_mean = float(
                    _masked_mean_tensor(
                        critic_contract_bootstrap_release_guard,
                        corridor_semantic_corridor_mask,
                    ).item()
                )
                critic_contract_bootstrap_negative_adv_pressure_mean = float(
                    _masked_mean_tensor(
                        critic_contract_bootstrap_negative_adv_pressure,
                        corridor_semantic_corridor_mask,
                    ).item()
                )
                critic_contract_bootstrap_trigger_surface_mean = float(
                    _masked_mean_tensor(
                        critic_contract_bootstrap_trigger_surface,
                        corridor_semantic_corridor_mask,
                    ).item()
                )
                critic_contract_bootstrap_regime_quality_gate_mean = float(
                    _masked_mean_tensor(
                        critic_contract_bootstrap_regime_quality_gate,
                        corridor_semantic_corridor_mask,
                    ).item()
                )
                critic_contract_bootstrap_regime_veto_active_mean = float(
                    _masked_mean_tensor(
                        (1.0 - critic_contract_bootstrap_regime_quality_gate).clamp(
                            0.0, 1.0
                        ),
                        corridor_semantic_corridor_mask,
                    ).item()
                )
                critic_contract_bootstrap_semantic_alarm = (
                    critic_contract_bootstrap_precontact_gate
                    * critic_contract_bootstrap_trigger_surface
                ).clamp(0.0, 1.0).detach()
                critic_contract_bootstrap_semantic_alarm_mean = float(
                    _masked_mean_tensor(
                        critic_contract_bootstrap_semantic_alarm,
                        corridor_semantic_corridor_mask,
                    ).item()
                )
                critic_contract_bootstrap_reward_alarm = float(
                    critic_contract_bootstrap_precontact_gate
                    * critic_contract_task_degradation
                )
                bootstrap_prev_state = float(
                    max(
                        0.0,
                        min(
                            1.0,
                            float(
                                getattr(
                                    self,
                                    "_adaptive_imag_critic_bootstrap_semantic_debt_state",
                                    0.0,
                                )
                            ),
                        ),
                    )
                )
                critic_contract_bootstrap_state = float(
                    min(
                        1.0,
                        max(
                            bootstrap_semantic_debt_decay * bootstrap_prev_state,
                            float(
                                critic_contract_bootstrap_semantic_alarm.max().item()
                            ),
                            critic_contract_bootstrap_reward_alarm,
                        ),
                    )
                )
                self._adaptive_imag_critic_bootstrap_semantic_debt_state = float(
                    critic_contract_bootstrap_state
                )
                critic_contract_bootstrap_semantic_debt = torch.maximum(
                    critic_contract_bootstrap_semantic_alarm,
                    corridor_semantic_corridor_mask
                    * critic_contract_bootstrap_state,
                ).clamp(0.0, 1.0).detach()
                critic_contract_bootstrap_semantic_debt_mean = float(
                    _masked_mean_tensor(
                        critic_contract_bootstrap_semantic_debt,
                        corridor_semantic_corridor_mask,
                    ).item()
                )
                critic_contract_bootstrap_pressure = torch.maximum(
                    critic_contract_semantic_pressure,
                    corridor_semantic_corridor_mask
                    * critic_contract_task_degradation,
                ).clamp(0.0, 1.0).detach()
                critic_contract_authority = (
                    1.0 - (
                        1.0 - critic_contract_bootstrap_pressure
                    ).clamp(min=actor_contract_trust_floor, max=1.0)
                ).clamp(0.0, 1.0).detach()
                critic_contract_authority_mean = float(
                    critic_contract_authority.mean().item()
                )
                critic_contract_authority_active_fraction = float(
                    (critic_contract_authority > 0.0).float().mean().item()
                )
                critic_contract_trust = (
                    1.0 - critic_contract_authority
                ).clamp(min=actor_contract_trust_floor, max=1.0).detach()
                critic_contract_trust_mean = float(
                    critic_contract_trust.mean().item()
                )
                critic_contract_trust_active_fraction = float(
                    (critic_contract_trust < 0.999).float().mean().item()
                )
                critic_contract_bootstrap_contact_drive = torch.maximum(
                    critic_contract_authority,
                    critic_contract_bootstrap_semantic_debt,
                ).clamp(0.0, 1.0).detach()
                critic_contract_bootstrap_contact_drive_mean = float(
                    critic_contract_bootstrap_contact_drive.mean().item()
                )
                critic_contract_bootstrap_precontact_gap_drive = (
                    critic_contract_bootstrap_contact_drive
                    + (
                        1.0 - critic_contract_bootstrap_contact_drive
                    ).clamp(min=0.0)
                    * critic_contract_bootstrap_release_guard
                ).clamp(0.0, 1.0).detach()
                critic_contract_bootstrap_precontact_gap_drive_mean = float(
                    critic_contract_bootstrap_precontact_gap_drive.mean().item()
                )
                critic_contract_bootstrap_precontact_need_mean = float(
                    _masked_mean_tensor(
                        critic_contract_bootstrap_precontact_gap_drive,
                        corridor_semantic_corridor_mask,
                    ).item()
                )
                bootstrap_precontact_takeover_floor = torch.clamp(
                    critic_contract_bootstrap_precontact_gate
                    * bootstrap_precontact_floor_max
                    * critic_contract_bootstrap_precontact_gap_drive,
                    min=0.0,
                    max=bootstrap_clean_mix_max,
                ).detach()
                critic_contract_bootstrap_precontact_floor = (
                    bootstrap_precontact_takeover_floor
                )
                critic_contract_bootstrap_precontact_floor_mean = float(
                    _masked_mean_tensor(
                        critic_contract_bootstrap_precontact_floor,
                        corridor_semantic_corridor_mask,
                    ).item()
                )
                bootstrap_surface_memory = torch.full_like(
                    critic_contract_bootstrap_contact_drive,
                    bootstrap_contact_persistence_floor
                    * critic_contract_bootstrap_surface_state,
                ).detach()
                critic_contract_bootstrap_surface_memory_mean = float(
                    _masked_mean_tensor(
                        bootstrap_surface_memory,
                        corridor_semantic_corridor_mask,
                    ).item()
                )
                bootstrap_anchor_focus_driver = torch.maximum(
                    torch.maximum(
                        critic_contract_bootstrap_semantic_debt,
                        critic_contract_authority,
                    ),
                    bootstrap_surface_memory,
                ).clamp(0.0, 1.0).detach()
                bootstrap_anchor_focus_weight = (
                    bootstrap_anchor_valid_mask * bootstrap_anchor_focus_driver
                ).detach()
                critic_contract_bootstrap_debt_focus_mean = float(
                    _masked_mean_tensor(
                        bootstrap_anchor_focus_driver,
                        bootstrap_anchor_valid_mask,
                    ).item()
                )
