    def _build_wm_batch(self) -> Optional[Dict[str, Tensor]]:
        """Build a world-model batch from replay buffer using WM-specific sizes."""
        if self.buffer is None:
            return None
        seq_len = int(getattr(self.config, "wm_seq_len", self.config.seq_len))
        max_remaining = 100
        world_model = getattr(self.model, "world_model", None)
        auditor = getattr(world_model, "consistency_auditor", None)
        auditor_cfg = getattr(auditor, "config", None)
        if auditor_cfg is not None:
            max_remaining = max(
                max_remaining,
                int(auditor_cfg.max_horizon + auditor_cfg.remaining_steps_margin),
            )

        batch = self.buffer.sample_sequences_with_remaining(
            batch_size=int(
                getattr(self.config, "wm_batch_size", self.config.batch_size)
            ),
            seq_len=seq_len,
            max_remaining=max_remaining,
        )
        if batch is None:
            return None
        return self._convert_batch_to_tensor(batch)

    def _select_rl_batch(
        self,
        real_batch: Optional[Dict[str, Tensor]],
        imag_batch: Optional[Dict[str, Tensor]],
    ) -> Tuple[Optional[Dict[str, Tensor]], str, float]:
        """Select RL batch source using scheduler."""
        has_real = real_batch is not None
        has_imag = imag_batch is not None
        if bool(getattr(self.config, "imagination_only", False)):
            if has_imag:
                return imag_batch, "imag", 1.0
            if has_real:
                return real_batch, "real", 1.0
            return None, "none", 1.0
        rho = self.scheduler.imag_ratio(self.global_step)

        if has_real and has_imag:
            metrics = getattr(self, "metrics", {})
            wm_ema = float(metrics.get("train/L_wm_ema", 0.0))
            critic_ema = float(metrics.get("train/L_critic_ema", 0.0))
            wm_guard = float(getattr(self.config, "imag_ratio_wm_guard", 6.0))
            critic_guard = float(getattr(self.config, "imag_ratio_critic_guard", 250.0))
            guard_floor = float(getattr(self.config, "imag_ratio_guard_floor", 0.05))
            if wm_ema > wm_guard or critic_ema > critic_guard:
                rho = min(rho, guard_floor)
            source = "imag" if np.random.rand() < rho else "real"
        elif has_real:
            source = "real"
        elif has_imag:
            source = "imag"
        else:
            source = None

        if source == "real" and real_batch is not None:
            return real_batch, "real", rho
        if source == "imag" and imag_batch is not None:
            return imag_batch, "imag", rho
        if real_batch is not None:
            return real_batch, "real", rho
        if imag_batch is not None:
            return imag_batch, "imag", rho
        return None, "none", rho



    # ── Episode tracking helpers ────────────────────────────────────────

    def _sync_episode_counts(
        self, data_collector: Optional[RolloutCollector]
    ):
        """Update episode_count and EMA from collector or buffer."""
        count = None
        if data_collector is not None:
            count = len(getattr(data_collector, "episode_returns", []))
        elif self.buffer is not None:
            count = getattr(self.buffer, "_episode_counter", None)
            if count is None:
                count = len(getattr(self.buffer, "episodes", []))

        if count is not None and count > self._last_episode_count:
            self.episode_count += count - self._last_episode_count
            self._last_episode_count = count

        if data_collector is not None and hasattr(
            data_collector, "episode_returns"
        ):
            rl = data_collector.episode_returns
            if len(rl) > self._last_return_episode_count:
                new = rl[self._last_return_episode_count :]
                self._last_return_episode_count = len(rl)
                self._update_episode_return_ema(new)
        elif self.buffer is not None:
            new_eps = self.buffer.get_new_completed_episodes(
                self._last_seen_episode_idx
            )
            if new_eps:
                self._last_seen_episode_idx = max(
                    int(ep.get("idx", self._last_seen_episode_idx))
                    for ep in new_eps
                )
                new_rets = [
                    float(ep["rewards"].sum())
                    for ep in new_eps
                    if "rewards" in ep
                ]
                if new_rets:
                    self._update_episode_return_ema(new_rets)

    # ── Data collection decision ────────────────────────────────────────

    def _should_collect(self) -> bool:
        """[FIX-11.2] Only collect when we've exhausted the training
        budget for the current data batch."""
        return self._steps_since_collect >= self.train_steps_per_cycle

    # ── Main loop ───────────────────────────────────────────────────────

    def run(
        self,
        num_steps: Optional[int] = None,
        eval_fn: Optional[Callable] = None,
        save_fn: Optional[Callable] = None,
        data_collector: Optional[RolloutCollector] = None,
        resume_from: Optional[str] = None,
        resume_restore_policy: Optional[TrainingCheckpointRestorePolicy] = None,
    ):
        """Run the main training loop.

        [FIX-11.2] Collection / training cycle:
          1. Collect ``collect_steps_per_cycle`` environment steps.
          2. Train for ``train_steps_per_cycle`` gradient updates.
          3. Repeat until ``num_steps`` total training steps are reached.

        This avoids the old pattern of collecting every single train step,
        which left the GPU idle during environment interaction.

        Parameters
        ----------
        num_steps : int, optional
            Total training steps.  Defaults to config value.
        eval_fn : callable, optional
            ``eval_fn(model, step) → metrics_dict``
        save_fn : callable, optional
            ``save_fn(model, step)``
        data_collector : RolloutCollector, optional
        resume_from : str, optional
            Checkpoint path for resumption.
        """
        if num_steps is None:
            num_steps = (
                getattr(self.config, "total_steps", None)
                or getattr(self.config, "num_train_steps", None)
                or getattr(self.config, "total_env_steps", 100_000)
            )

        resumed_from_checkpoint = False
        if resume_from is not None and os.path.exists(resume_from):
            ts = TrainingStateManager.load(
                resume_from,
                self.config,
                self.device,
                model=self.model,
                opt_bundle=self.opt_bundle,
                buffer=self.buffer,
                trusted_source=True,
                restore_policy=resume_restore_policy,
                current_effective_training_config=self.config,
            )
            self.global_step = ts.global_step
            self.episode_count = ts.episode_count
            self.env_steps_collected = int(getattr(ts, "total_samples", 0))
            self._episode_return_ema = float(getattr(ts, "episode_return_ema", 0.0))
            self._episode_return_initialized = bool(getattr(ts, "episode_return_initialized", False))
            self._last_episode_count = int(getattr(ts, "last_episode_count", 0))
            self._last_return_episode_count = int(getattr(ts, "last_return_episode_count", 0))
            self._last_seen_episode_idx = int(getattr(ts, "last_seen_episode_idx", -1))
            self._restore_adaptive_compensation_state(
                getattr(ts, "adaptive_compensation_state", {}),
                fallback_best_step=int(getattr(ts, "best_step", -1)),
                fallback_best_eval=float(
                    getattr(ts, "best_eval_return", -float("inf"))
                ),
                strict=True,
            )
            self._steps_since_collect = _resolve_resume_steps_since_collect(
                ts,
                global_step=self.global_step,
                train_steps_per_cycle=self.train_steps_per_cycle,
            )
            resumed_from_checkpoint = True
            logger.info(f"Resumed from step {self.global_step}")

        logger.info(
            f"Starting training for {num_steps} steps "
            f"(collect {self.collect_steps_per_cycle} steps, "
            f"train {self.train_steps_per_cycle} updates per cycle)"
        )

        # Force initial collection
        if not resumed_from_checkpoint:
            self._steps_since_collect = self.train_steps_per_cycle
        imagination_only = bool(getattr(self.config, "imagination_only", False))
        wm_pretrain_steps = int(getattr(self.config, "wm_pretrain_steps", 0))
        warmup_steps = int(getattr(self.config, "warmup_steps", 0))
        warmup_end = wm_pretrain_steps + warmup_steps

        while self.global_step < num_steps:
            # ── Phase 1: Collect data (only when due) ───────────────────
            if data_collector is not None and self._should_collect():
                collect_num_steps = int(self.collect_steps_per_cycle)
                target_env_steps = int(getattr(self.config, "total_env_steps", 0) or 0)
                if target_env_steps > 0:
                    remaining_env_steps = target_env_steps - int(self.env_steps_collected)
                    if remaining_env_steps <= 0:
                        raise RuntimeError(
                            "Target env-step budget exhausted before reaching target update budget"
                        )
                    collect_num_steps = min(collect_num_steps, int(remaining_env_steps))
                result = data_collector.collect(
                    num_steps=collect_num_steps
                )
                if result is None:
                    raise RuntimeError(
                        "Data collector returned None instead of raising on collection failure"
                    )
                self._add_to_buffer(result)
                self._steps_since_collect = 0
                self._sync_episode_counts(data_collector)
            elif data_collector is None:
                self._sync_episode_counts(None)

            # ── Phase 2: Build real/imag batches ───────────────────────
            real_batch = self._build_real_batch()
            try:
                imag_batch = self._build_imagined_batch(reference_real_batch=real_batch)
            except TypeError as exc:
                if "reference_real_batch" not in str(exc):
                    raise
                imag_batch = self._build_imagined_batch()
            wm_real_batch = self._build_wm_batch()
            if wm_real_batch is None:
                wm_real_batch = real_batch

            if imagination_only and imag_batch is None:
                if self.imagination_engine is None:
                    raise RuntimeError(
                        "Imagination-only enabled but imagination_engine is None"
                    )
                if data_collector is None:
                    raise RuntimeError(
                        "Imagination-only enabled but no seed data is available and no data collector is configured"
                    )
                else:
                    logger.warning("Imagination-only enabled but no seed data available")
                self._steps_since_collect = self.train_steps_per_cycle
                time.sleep(0.1)
                continue

            rl_batch, source_tag, imag_ratio = self._select_rl_batch(
                real_batch=real_batch,
                imag_batch=imag_batch,
            )
            if rl_batch is None:
                if data_collector is None:
                    raise RuntimeError(
                        "No available batch (real/imag) and no data collector is configured"
                    )
                logger.warning("No available batch (real/imag), skipping step")
                self._steps_since_collect = self.train_steps_per_cycle
                time.sleep(0.1)
                continue

            # ── Phase policy: wm_pretrain -> warmup -> main ─────────────
            skip_rl = False
            if self.global_step < wm_pretrain_steps:
                phase = "wm_pretrain"
                skip_rl = True
            elif self.global_step < warmup_end:
                phase = "warmup"
                if imagination_only:
                    skip_rl = True
            else:
                phase = "main"

            rl_batch_for_step = rl_batch
            source_for_step = source_tag
            imag_ratio_for_step = imag_ratio
            if phase == "warmup" and real_batch is not None:
                rl_batch_for_step = real_batch
                source_for_step = "warmup_real"
                imag_ratio_for_step = 0.0
            elif phase == "wm_pretrain":
                source_for_step = "wm_pretrain"
                imag_ratio_for_step = 0.0

            # ── Phase 3: Train (WM real-only by default) ───────────────
            # Keep WM grounded on real trajectories in imagination-only mode.
            if imagination_only:
                wm_batch = wm_real_batch
            else:
                wm_batch = (
                    wm_real_batch
                    if bool(getattr(self.config, "wm_real_only", True))
                    else (wm_real_batch if wm_real_batch is not None else rl_batch)
                )

            if skip_rl and wm_batch is None:
                if data_collector is None:
                    raise RuntimeError(
                        "Skip-RL phase requires WM batch but no data collector is configured"
                    )
                logger.warning("Skip-RL phase requires WM batch but none is available; collecting more data.")
                self._steps_since_collect = self.train_steps_per_cycle
                time.sleep(0.1)
                continue
            value_real_batch = None
            if source_for_step == "imag" and real_batch is not None:
                value_real_batch = real_batch
            metrics = self.train_step(
                rl_batch=rl_batch_for_step,
                wm_batch=wm_batch,
                value_real_batch=value_real_batch,
                source_tag=source_for_step,
                imag_ratio=imag_ratio_for_step,
                skip_rl=skip_rl,
            )
            metrics["train/phase"] = phase
            self._steps_since_collect += 1

            # ── Phase 4: Log / eval / save ──────────────────────────────
            if self.should_log():
                self.logger_fn(metrics, self.global_step)

            stop_requested = False
            if self.should_eval() and eval_fn is not None:
                eval_metrics = eval_fn(self.model, self.global_step)
                self.logger_fn({"eval": eval_metrics}, self.global_step)
                stop_requested = bool(eval_metrics.get("stop_training", False)) if isinstance(eval_metrics, dict) else False

            if self.should_save() and save_fn is not None:
                save_fn(self.model, self.global_step)

            if stop_requested:
                logger.info("Early stop requested at step %d", self.global_step)
                break

        logger.info("Training complete!")


