# ══════════════════════════════════════════════════════════════════════════════
#  SECTION 12 ▸ AUXILIARY TOOLS (Noise · Gradient · Router)
# ══════════════════════════════════════════════════════════════════════════════
#
#  Depends on: (standalone)
#
#  Public API
#  ──────────
#    NoiseInjector       — trainable noise with decay
#    GradientClipper     — clip-by-norm / value / adaptive
#    GradientAccumulator — accumulate gradients over K steps
#    router_mode_context — context manager for router.mode switching
# ══════════════════════════════════════════════════════════════════════════════


class NoiseInjector(nn.Module):
    """Gaussian noise injection with exponential decay.

    [FIX-NI] ``enabled`` is stored as a plain Python bool (not a float
    buffer), improving clarity and avoiding float-to-bool confusion
    in ``state_dict``.  The noise parameters themselves remain buffers
    so they are persisted.

    Parameters
    ----------
    noise_std : float
    decay_rate : float
    min_noise : float
    """

    def __init__(
        self,
        noise_std: float = 0.1,
        decay_rate: float = 0.999,
        min_noise: float = 0.01,
    ):
        super().__init__()
        self.register_buffer("noise_std", torch.tensor(noise_std))
        self.register_buffer("decay_rate", torch.tensor(decay_rate))
        self.register_buffer("min_noise", torch.tensor(min_noise))
        self._enabled = True  # plain bool, not a buffer

    @property
    def enabled(self) -> bool:
        return self._enabled

    @enabled.setter
    def enabled(self, value: bool):
        self._enabled = bool(value)

    def forward(self, x: Tensor) -> Tensor:
        if not self.training or not self._enabled:
            return x
        return x + torch.randn_like(x) * self.noise_std

    def decay(self):
        """Reduce ``noise_std`` by ``decay_rate``, clamping at ``min_noise``."""
        self.noise_std.copy_(
            torch.maximum(self.noise_std * self.decay_rate, self.min_noise)
        )

    def get_config(self) -> Dict[str, Any]:
        return {
            "noise_std": self.noise_std.item(),
            "decay_rate": self.decay_rate.item(),
            "min_noise": self.min_noise.item(),
            "enabled": self._enabled,
        }

    def set_config(self, cfg: Dict[str, Any]):
        if "noise_std" in cfg:
            self.noise_std.fill_(cfg["noise_std"])
        if "decay_rate" in cfg:
            self.decay_rate.fill_(cfg["decay_rate"])
        if "min_noise" in cfg:
            self.min_noise.fill_(cfg["min_noise"])
        if "enabled" in cfg:
            self._enabled = bool(cfg["enabled"])

    # Override state_dict to include _enabled
    def state_dict(self, *args, **kwargs):
        sd = super().state_dict(*args, **kwargs)
        sd["_enabled"] = self._enabled
        return sd

    def load_state_dict(self, state_dict, strict=True):
        self._enabled = state_dict.pop("_enabled", True)
        super().load_state_dict(state_dict, strict=strict)


class GradientClipper:
    """Gradient clipping with selectable strategy.

    Parameters
    ----------
    max_norm : float
    norm_type : float
    clip_method : ``"norm"`` | ``"value"`` | ``"adaptive"``
    """

    def __init__(
        self,
        max_norm: float = 1.0,
        norm_type: float = 2.0,
        clip_method: str = "norm",
    ):
        assert clip_method in ("norm", "value", "adaptive")
        self.max_norm = max_norm
        self.norm_type = norm_type
        self.clip_method = clip_method

    def clip(self, parameters) -> float:
        """Clip gradients and return the (pre-clip) total norm."""
        params = list(parameters)
        if self.clip_method == "norm":
            return torch.nn.utils.clip_grad_norm_(
                params, self.max_norm, norm_type=self.norm_type
            ).item()
        elif self.clip_method == "value":
            torch.nn.utils.clip_grad_value_(params, self.max_norm)
            return self._compute_norm(params)
        else:
            return self._clip_adaptive(params)

    def _compute_norm(self, params) -> float:
        total = 0.0
        for p in params:
            if p.grad is not None:
                total += p.grad.data.norm(self.norm_type).item() ** self.norm_type
        return total ** (1.0 / self.norm_type) if total > 0 else 0.0

    def _clip_adaptive(self, params) -> float:
        total_norm = self._compute_norm(params)
        if total_norm > 0:
            clip_coef = self.max_norm / (total_norm + 1e-6)
            if clip_coef < 1.0:
                for p in params:
                    if p.grad is not None:
                        p.grad.data.mul_(clip_coef)
        return total_norm


class GradientAccumulator:
    """Track gradient accumulation steps.

    Parameters
    ----------
    accumulation_steps : int
        Number of forward-backward passes before ``optimizer.step()``.
    """

    def __init__(self, accumulation_steps: int = 1):
        self.accumulation_steps = max(accumulation_steps, 1)
        self.current_step = 0

    def should_update(self) -> bool:
        """Increment counter; return ``True`` when it's time to step."""
        self.current_step += 1
        if self.current_step >= self.accumulation_steps:
            self.current_step = 0
            return True
        return False

    def scale_loss(self, loss: Tensor) -> Tensor:
        return loss / self.accumulation_steps

    def reset(self):
        self.current_step = 0


@contextmanager
def router_mode_context(router: nn.Module, mode: str):
    """Temporarily switch ``router.mode`` and restore it on exit.

    If *router* has no ``mode`` attribute, this is a no-op.
    """
    if not hasattr(router, "mode"):
        yield
        return
    original = getattr(router, "mode", None)
    try:
        router.mode = mode
        yield
    finally:
        if original is not None:
            router.mode = original


