#  SECTION 13 ▸ VALIDATION & STATISTICS
# ══════════════════════════════════════════════════════════════════════════════
#
#  Depends on: (standalone)
#
#  Public API
#  ──────────
#    BranchValidator            — batch / model-output / gradient checks
#    validate_training_data()   — quick batch sanity check
#    compute_data_statistics()  — mean / std / min / max per tensor
# ══════════════════════════════════════════════════════════════════════════════


class BranchValidator:
    """Training data validator with rate-limited warnings.

    Parameters
    ----------
    max_warnings : int
        Suppress further warnings after this many.
    """

    def __init__(self, max_warnings: int = 5):
        self.max_warnings = max_warnings
        self.warning_count = 0

    def _warn(self, msg: str):
        if self.warning_count < self.max_warnings:
            logger.warning(f"[BranchValidator] {msg}")
            self.warning_count += 1
            if self.warning_count == self.max_warnings:
                logger.warning("[BranchValidator] max warnings reached")

    def validate_batch(
        self,
        batch: Dict[str, Tensor],
        expected_keys: Optional[List[str]] = None,
    ) -> bool:
        """Check key presence and shape consistency."""
        if expected_keys is None:
            expected_keys = ["vitals", "actions", "rewards", "dones"]

        missing = set(expected_keys) - set(batch.keys())
        if missing:
            self._warn(f"Missing keys: {missing}")
            return False

        batch_size = None
        seq_len = None
        for key in expected_keys:
            t = batch.get(key)
            if t is None or not isinstance(t, torch.Tensor):
                self._warn(f"{key} is not a tensor")
                return False
            if t.dim() < 2:
                self._warn(f"{key} has insufficient dims: {t.shape}")
                return False
            if batch_size is None:
                batch_size = t.shape[0]
            elif t.shape[0] != batch_size:
                self._warn(f"Batch mismatch for {key}: {t.shape[0]} vs {batch_size}")
                return False
            if key in ("actions", "rewards", "dones"):
                if seq_len is None:
                    seq_len = t.shape[1]
                elif t.shape[1] != seq_len:
                    self._warn(f"Seq len mismatch for {key}")
                    return False
            elif key == "vitals":
                if seq_len is not None and t.shape[1] not in (seq_len, seq_len + 1):
                    self._warn(f"Vitals seq len mismatch: {t.shape[1]}")
                    return False
        return True

    def validate_gradient_flow(self, model: nn.Module) -> bool:
        """Check that gradients exist and are finite."""
        has_grad = False
        for name, p in model.named_parameters():
            if p.grad is not None:
                has_grad = True
                if torch.isnan(p.grad).any():
                    self._warn(f"NaN gradient in {name}")
                    return False
                if torch.isinf(p.grad).any():
                    self._warn(f"Inf gradient in {name}")
                    return False
        if not has_grad:
            self._warn("No gradients found")
            return False
        return True


def validate_training_data(
    batch: Dict[str, Tensor],
    config: Any = None,
) -> Tuple[bool, Optional[str]]:
    """Quick sanity check on a training batch.

    Returns ``(is_valid, error_message_or_None)``.
    """
    for key in ("vitals", "actions", "rewards", "dones"):
        if key not in batch:
            return False, f"Missing key: {key}"

    bs = batch["vitals"].shape[0]
    sl = batch["actions"].shape[1]

    if batch["vitals"].dim() >= 2 and batch["vitals"].shape[1] != sl + 1:
        return False, (
            f"vitals seq len {batch['vitals'].shape[1]} != actions seq len + 1 ({sl + 1})"
        )
    if batch["actions"].shape[0] != bs:
        return False, "actions batch size mismatch"
    if torch.isnan(batch["vitals"]).any():
        return False, "NaN in vitals"
    if torch.isnan(batch["actions"]).any():
        return False, "NaN in actions"
    if (batch["dones"] < 0).any() or (batch["dones"] > 1).any():
        return False, "dones out of [0, 1]"
    return True, None


def compute_data_statistics(batch: Dict[str, Tensor]) -> Dict[str, Any]:
    """Compute per-key mean / std / min / max."""
    stats: Dict[str, Any] = {}
    for key, t in batch.items():
        if isinstance(t, torch.Tensor) and t.is_floating_point():
            stats[f"{key}/mean"] = t.mean().item()
            stats[f"{key}/std"] = t.std().item() if t.numel() > 1 else 0.0
            stats[f"{key}/min"] = t.min().item()
            stats[f"{key}/max"] = t.max().item()
            stats[f"{key}/shape"] = list(t.shape)
    return stats


# ══════════════════════════════════════════════════════════════════════════════
#  END OF SECTION 13
# ══════════════════════════════════════════════════════════════════════════════


# ══════════════════════════════════════════════════════════════════════════════
#  SECTION 14 ▸ EVALUATION
# ══════════════════════════════════════════════════════════════════════════════
#
#  Depends on: SECTION 1  (extract_real_value)
#              SECTION 10 (_ensure_env_wrapper, _convert_action_for_env)
#
#  Public API
#  ──────────
#    run_eval_episode()     — single deterministic episode
#    run_evaluation()       — multi-episode evaluation
# ══════════════════════════════════════════════════════════════════════════════


def run_eval_episode(
    model: nn.Module,
    env: Any,
    max_steps: int = 1000,
    device: Optional[torch.device] = None,
) -> Tuple[float, int]:
    """Run one deterministic evaluation episode.

    Returns ``(total_reward, episode_length)``.
    """
    if device is None:
        device = next(model.parameters()).device

    env = _ensure_env_wrapper(env)
    obs = env.reset()
    obs_t = torch.from_numpy(np.asarray(obs, dtype=np.float32)).unsqueeze(0).to(device)

    total_reward = 0.0
    length = 0

    for _ in range(max_steps):
        with torch.no_grad():
            dist, _ = model(obs_t)
            action = dist.mode if hasattr(dist, "mode") else dist.mean

        action_env = _convert_action_for_env(action[0], env)
        next_obs, reward, terminated, truncated, info = env.step(action_env)

        total_reward += float(reward)
        length += 1

        if terminated or truncated:
            break

        obs_t = torch.from_numpy(
            np.asarray(next_obs, dtype=np.float32)
        ).unsqueeze(0).to(device)

    return total_reward, length


def run_evaluation(
    model: nn.Module,
    env: Any,
    num_episodes: int = 10,
    max_steps: int = 1000,
    device: Optional[torch.device] = None,
) -> Dict[str, float]:
    """Run *num_episodes* deterministic episodes and return statistics.

    The model is set to eval mode during evaluation and restored afterwards.
    """
    was_training = bool(model.training)
    model.eval()
    returns, lengths = [], []
    for _ in range(num_episodes):
        r, l = run_eval_episode(model, env, max_steps, device)
        returns.append(r)
        lengths.append(l)
    model.train(was_training)

    return {
        "mean_return": float(np.mean(returns)),
        "std_return": float(np.std(returns)),
        "mean_length": float(np.mean(lengths)),
        "min_return": float(np.min(returns)),
        "max_return": float(np.max(returns)),
    }


# ══════════════════════════════════════════════════════════════════════════════
#  END OF SECTION 14
# ══════════════════════════════════════════════════════════════════════════════


# ══════════════════════════════════════════════════════════════════════════════
#  SECTION 15 ▸ PERFORMANCE BENCHMARKING
# ══════════════════════════════════════════════════════════════════════════════
#
#  Depends on: (standalone)
#
#  Public API
#  ──────────
#    PerformanceBenchmark  — wall-clock timing
#    MemoryProfiler        — CUDA memory snapshots
# ══════════════════════════════════════════════════════════════════════════════


class PerformanceBenchmark:
    """Wall-clock timing for arbitrary callables."""

    def __init__(self):
        self.results: Dict[str, List[float]] = {}

    def measure(
        self,
        name: str,
        fn: Callable,
        num_runs: int = 10,
        warmup_runs: int = 2,
    ) -> Dict[str, float]:
        for _ in range(warmup_runs):
            fn()

        times = []
        for _ in range(num_runs):
            if torch.cuda.is_available():
                torch.cuda.synchronize()
            t0 = time.perf_counter()
            fn()
            if torch.cuda.is_available():
                torch.cuda.synchronize()
            times.append(time.perf_counter() - t0)

        arr = np.array(times)
        self.results.setdefault(name, []).extend(times)
        return {
            "mean": float(arr.mean()),
            "std": float(arr.std()),
            "min": float(arr.min()),
            "max": float(arr.max()),
            "median": float(np.median(arr)),
        }

    def compare(
        self, configs: Dict[str, Callable], num_runs: int = 10,
    ) -> Dict[str, Dict[str, float]]:
        return {name: self.measure(name, fn, num_runs) for name, fn in configs.items()}

    def get_summary(self) -> Dict[str, Any]:
        summary = {}
        for name, times in self.results.items():
            arr = np.array(times)
            summary[name] = {
                "count": len(arr),
                "mean": float(arr.mean()),
                "std": float(arr.std()),
                "min": float(arr.min()),
                "max": float(arr.max()),
                "p95": float(np.percentile(arr, 95)),
                "p99": float(np.percentile(arr, 99)),
            }
        return summary


class MemoryProfiler:
    """CUDA memory usage snapshots."""

    def __init__(self):
        self.snapshots: List[Dict[str, Any]] = []

    def snapshot(self, label: str = ""):
        if not torch.cuda.is_available():
            return
        self.snapshots.append({
            "label": label,
            "timestamp": time.time(),
            "allocated_mb": torch.cuda.memory_allocated() / 1024 ** 2,
            "reserved_mb": torch.cuda.memory_reserved() / 1024 ** 2,
            "max_allocated_mb": torch.cuda.max_memory_allocated() / 1024 ** 2,
        })

    def get_peak_memory(self) -> float:
        if not self.snapshots:
            return 0.0
        return max(s["allocated_mb"] for s in self.snapshots)

    def get_memory_diff(self, start_label: str, end_label: str) -> float:
        start = end = None
        for s in self.snapshots:
            if s["label"] == start_label:
                start = s
            if s["label"] == end_label:
                end = s
        if start is None or end is None:
            return 0.0
        return end["allocated_mb"] - start["allocated_mb"]

    def clear(self):
        self.snapshots.clear()
        if torch.cuda.is_available():
            torch.cuda.reset_peak_memory_stats()


