def create_replay_buffer(
    capacity: int = 1000,
    store_obs: bool = False,
    auto_compute_remaining: bool = True,
) -> ReplayBuffer:
    """Build a :class:`ReplayBuffer`."""
    return ReplayBuffer(
        capacity=capacity,
        store_obs=store_obs,
        auto_compute_remaining=auto_compute_remaining,
    )


